insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('palaeae-rasumovsky', 'Palää Rasumovsky', '', '', '', 'Wiener Prachtpalais', 'Palais Rasumovsky', '[{"kategorie": "allg.", "text": "bedeutendes klassizistisches Bauwerk im 3. Wiener Gemeindebezirk ([[Landstraße]]) in der Rasumovskygasse"}, {"kategorie": "", "text": "Es liegt in einem ruhigen Wohnviertel und ist von einem weitläufigen Garten umgeben, der das Palais vom städtischen Trubel abschirmt"}, {"kategorie": "", "text": "Das Palais wurde zwischen 1806 und 1807 im Auftrag von Andrei Kirillowitsch Rasumofsky, einem russischen Adligen und Diplomaten, errichtet. Rasumofsky war Botschafter des Zaren in Wien und spielte eine zentrale Rolle im Wiener Kongress von 1814/15. Das Palais diente ihm als Residenz und als Ort für gesellschaftliche Zusammenkünfte, bei denen er die kulturelle Elite Wiens empfing"}, {"kategorie": "", "text": "Das Palais Rasumofsky wurde vom Architekten Louis Montoyer im Stil des [[Klassizismus]] entworfen. Es zeichnet sich durch seine harmonischen Proportionen, die schlichte Eleganz der Fassade und die großzügige Raumaufteilung aus"}, {"kategorie": "", "text": "Besonders bemerkenswert ist der Hauptsaal des Palais, der als prachtvoller Empfangsraum diente und von Rasumofsky für Konzerte und gesellschaftliche Veranstaltungen genutzt wurde. Der Saal ist mit kunstvollen Stuckarbeiten, Fresken und einem Marmorkamin ausgestattet"}, {"kategorie": "", "text": "Rasumofsky war ein großer Förderer von Ludwig van Beethoven, der ihm seine \"Rasumofsky-Quartette\" widmete. Diese Streichquartette zählen zu den wichtigsten Werken der Kammermusik und sind eng mit der Geschichte des Palais verbunden."}]'::jsonb, ''),
  ('palaeae-schwoaznbeag', 'Palää Schwoaznbeag', '', '', '', 'Wiener Prachtpalais', 'Palais Schwarzenberg', '[{"kategorie": "allg.", "text": "prächtiges Barockpalais im 3. Wiener Gemeindebezirk ([[Landstraße]]) und eines der bedeutendsten historischen Gebäude Wiens"}, {"kategorie": "", "text": "Das Palais Schwarzenberg liegt im Herzen von Wien, nahe dem [[Schloss]] Belvedere und dem [[Schwarzenbergplatz]]"}, {"kategorie": "", "text": "Der Bau des Palais Schwarzenberg begann im Jahr 1697 und wurde 1728 abgeschlossen. Es wurde im Auftrag von Prinz Adam Franz von Schwarzenberg errichtet, einem bedeutenden Mitglied des Hauses Schwarzenberg, das zu den einflussreichsten Adelsfamilien des Habsburgerreichs gehörte"}, {"kategorie": "", "text": "Der Architekt Johann Lucas von Hildebrandt, einer der bedeutendsten Barockbaumeister der Zeit, entwarf das Palais. Im Laufe der Jahrhunderte diente das Palais als Residenz der Familie Schwarzenberg und als Ort für festliche Veranstaltungen und Empfänge"}, {"kategorie": "", "text": "Das Palais Schwarzenberg ist ein herausragendes Beispiel für den österreichischen Barock. Die Architektur zeichnet sich durch ihre monumentale Fassade, reich verzierte Stuckarbeiten und eine imposante Raumaufteilung aus"}, {"kategorie": "", "text": "Besonders bemerkenswert sind der Festsaal und die prunkvollen Innenräume, die mit Fresken, Marmor und vergoldeten Dekorationen ausgestattet sind. Die barocke Pracht des Palais spiegelt den Reichtum und den Einfluss der Familie Schwarzenberg wider"}, {"kategorie": "", "text": "Zum Palais Schwarzenberg gehört auch ein weitläufiger barocker Garten, der nach französischem Vorbild gestaltet wurde. Der Garten umfasst gepflegte Rasenflächen, kunstvoll geschnittene Hecken, Statuen und Brunnen, die den eleganten Stil des Barock widerspiegeln."}]'::jsonb, ''),
  ('bruno-kreisky-park', 'Bruno-Kreisky-Park', '', '', '', 'Wiener Parks und Parkanlagen', 'Bruno-Kreisky-Park', '[{"kategorie": "allg.", "text": "städtischer Park im 5. Wiener Gemeindebezirk ([[Margareten]]), benannt nach dem ehemaligen österreichischen Bundeskanzler Dr. Bruno Kreisky"}, {"kategorie": "", "text": "Der Park dient als öffentliche Grünfläche, Begegnungsraum und Naherholungsort für die Bevölkerung des dicht besiedelten innerstädtischen Bezirks. Es ist einer der wenigen größeren Parks im innerstädtischen Margareten, daher besonders wichtig für das Stadtklima und die Lebensqualität."}]'::jsonb, ''),
  ('teata-aun-da-wiin', 'Teata aun da Wiin', '', '', '', 'Wiener Theater, Bühnen und Aufführungsstätten', 'Theater an der Wien', '[{"kategorie": "wörtlich, eigentlich", "text": "\"Theater am Wienfluss\""}, {"kategorie": "", "text": "eines der bedeutendsten und traditionsreichsten Opernhäuser in Wien, das für seine erstklassigen Musiktheaterproduktionen und seine historische Bedeutung bekannt ist"}, {"kategorie": "", "text": "Es befindet sich im 6. Wiener Gemeindebezirk ([[Mariahilf]]) und hat eine lange Geschichte als wichtiger Ort für Musik und Theater in der österreichischen Hauptstadt"}, {"kategorie": "", "text": "Das Theater an der Wien wurde 1801 vom Theaterdirektor Emanuel Schikaneder gegründet, der auch als Librettist und erster Papageno der „Zauberflöte“ von Wolfgang Amadeus Mozart bekannt ist. Das Theater wurde schnell zu einem wichtigen Zentrum für Musiktheater in Wien"}, {"kategorie": "", "text": "Ludwig van Beethoven, einer der größten Komponisten der Musikgeschichte, hatte eine enge Verbindung zum Theater an der Wien. Hier wurde seine Oper „Fidelio“ 1805 uraufgeführt, und Beethoven selbst lebte für einige Zeit im Theatergebäude"}, {"kategorie": "", "text": "Das Theater an der Wien ist ein prachtvoller Bau im klassizistischen Stil mit barocken Elementen. Die Fassade des Theaters, die von Oberbaurat Franz Jäger entworfen wurde, ist beeindruckend und verleiht dem Gebäude einen repräsentativen Charakter"}, {"kategorie": "", "text": "Das Innere des Theaters ist ebenso prächtig, mit einem reich verzierten Zuschauerraum, der für seine hervorragende Akustik bekannt ist"}, {"kategorie": "", "text": "Das Theater legt großen Wert auf historische Aufführungspraxis und arbeitet regelmäßig mit renommierten Regisseuren, Dirigenten und Ensembles zusammen. Besonders die Aufführung von Barockopern und Opern des 18. und 19. Jahrhunderts hat sich als Spezialität des Theaters etabliert"}, {"kategorie": "", "text": "Das Theater an der Wien ist zudem der Hauptspielort der [[Wiener]] Festwochen, ein internationales Kunstfestival, das jährlich in Wien stattfindet und für seine innovativen und anspruchsvollen Produktionen bekannt ist."}]'::jsonb, ''),
  ('teata-aun-da-gumpnduafaschdroossn', 'Teata aun da Gumpnduafaschdroossn', '', '', '', 'Wiener Theater, Bühnen und Aufführungsstätten', 'Theater an der Gumpendorferstraße', '[{"kategorie": "allg.", "text": "\"zeitgenössisches Theaterhaus (abgekürzt \"TAG\") im 6. Wiener Gemeindebezirk ([[Mariahilf]])"}, {"kategorie": "", "text": "Es gilt als eines der innovativsten Off-Theater Wiens mit hohem künstlerischem Anspruch und gesellschaftspolitischer Relevanz. Das TAG steht für neue Theaterformen, experimentelle Inszenierungen, originäre Stückentwicklungen und eine starke Verbindung zum urbanen Publikum"}, {"kategorie": "", "text": "Gegründet wurde das TAG im Jahr 2005, es befindet sich in einem Gebäude, das bereits vor der Neugründung als Kleinkunst- und Kabarettbühne genutzt wurde. Seit 2005 wurde es zu einem professionellen Ensemble-Theater mit klarem programmatischen Profil entwickelt"}, {"kategorie": "", "text": "Das TAG arbeitet mit einem festen Schauspielensemble und einem künstlerischen Leitungsteam, das kollektive Entscheidungsstrukturen fördert. Häufig werden Regie, Dramaturgie und Bühne gemeinsam entwickelt – das macht die Produktionen besonders konsistent und kreativ"}, {"kategorie": "", "text": "Das Theater an der Gumpendorfer Straße (TAG) ist ein Leuchtturm des freien Theaters in Wien – ein Ort, an dem Theaterkunst, Zeitgeist und gesellschaftliche Reflexion aufeinandertreffen. Es verbindet künstlerische Qualität, soziales Engagement und urbanen Humor. Das TAG ist wienerisch, kritisch, kreativ – und damit ein Fixpunkt in der Wiener Kulturlandschaft."}]'::jsonb, ''),
  ('wiina-festwochn', 'Wiina Festwochn', '', '', '', 'Wiener Theater, Bühnen und Aufführungsstätten', 'Wiener Festwochen', '[{"kategorie": "allg.", "text": "\"international renommiertes Kunst- und Kulturfestival, das jedes Jahr in Wien stattfindet\""}, {"kategorie": "", "text": "Die Wiener Festwochen gehören zu den bedeutendsten und ältesten Festivals ihrer Art in Europa und bieten ein vielseitiges Programm, das Theater, Musik, Tanz, Performance und bildende Kunst umfasst"}, {"kategorie": "", "text": "Sie wurden erstmals 1951 ins Leben gerufen, kurz nach dem Zweiten Weltkrieg, als Teil der Bemühungen, die Stadt Wien als ein Zentrum der Kultur und Kunst wiederaufzubauen und zu etablieren"}, {"kategorie": "", "text": "Das Programm der Wiener Festwochen ist bekannt für seine künstlerische Vielfalt und seinen internationalen Charakter. Es umfasst Produktionen aus den Bereichen Theater, Oper, Tanz, Musik, Performance und bildende Kunst"}, {"kategorie": "", "text": "Die Wiener Festwochen nutzen zahlreiche Spielstätten in Wien, darunter einige der renommiertesten Theater und Konzerthallen der Stadt. Zu den wichtigsten Orten zählen das [[Burgtheater]], das [[Akademietheater]], das [[Theater]] an der Wien, das [[Volkstheater]] und der [[Wiener]] Musikverein."}]'::jsonb, ''),
  ('palaeae-strozzi', 'Palää Strozzi', '', '', '', 'Wiener Prachtpalais', 'Palais Strozzi', '[{"kategorie": "allg.", "text": "barockes Stadtpalais im 8. Wiener Gemeindebezirk Josefstadt, das im 18. Jahrhundert erbaut wurde. Es zählt zu den bedeutenden Palaisbauten Wiens und wurde im Laufe seiner Geschichte für verschiedene kulturelle, wissenschaftliche und politische Zwecke genutzt. Heute ist es ein öffentlicher Gebäudekomplex, der unter anderem vom Bundesdenkmalamt und Universitätseinrichtungen genutzt wird"}, {"kategorie": "", "text": "Erbaut wurde das Palais 1699–1705 im Auftrag des Grafen Aron Franz von Strozzi im Stil des frühen österreichischen [[Barock]]. Der Namensgeber, die Familie Strozzi, war ein bedeutendes Adelsgeschlecht mit florentinischen Wurzeln. Nach dem Tod des Erbauers wechselte das Palais Strozzo mehrfach den Besitzer und befand sich seit dem 19. Jahrhundert in staatlicher Nutzung (u. a. als Militärspital, Erziehungsanstalt, Verwaltungssitz)"}, {"kategorie": "", "text": "Das Palais Strozzi ist ein charakteristisches barockes Palais mit symmetrischer Fassade, monumentalem Ehrenhof (Cour d’honneur) und repräsentativem Portal. Es handelt sich um eine Dreiflügelanlage mit großzügigen Innenhöfen (spätere Zubauten wurden im 19. Jahrhundert integriert, dennoch denkmalgeschützt)"}, {"kategorie": "", "text": "Das Palais Strozzi ist heute kein Museum oder Wohnsitz mehr, sondern dient als Sitz öffentlicher Institutionen (Bundesdenkmalamt, Teile der Universität Wien, insbesondere Forschungsplattformen, sowie Archiv- und Verwaltungsräume)."}]'::jsonb, ''),
  ('josefschdaedta-schdrossn', 'Josefschdädta Schdrossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Josefstädter Straße', '[{"kategorie": "allg.", "text": "wichtige Verkehrs- und Einkaufsstraße im 8. Wiener Gemeindebezirk ([[Josefstadt]]), die sich vom westlichen Rand der Wiener Innenstadt bis zum [[Gürtel]] erstreckt"}, {"kategorie": "", "text": "Sie ist eine der ältesten Straßen Wiens und entwickelte sich im Mittelalter als wichtige Verbindungsstraße zwischen dem Stadtzentrum und den westlichen Vororten"}, {"kategorie": "", "text": "Ihr Name leitet sich vom Bezirk Josefstadt ab, der nach Kaiser Joseph II. benannt ist"}, {"kategorie": "", "text": "Die Josefstädter Straße ist geprägt von einer Mischung aus historischen Gebäuden aus der Gründerzeit und dem Biedermeier sowie modernen Bauten. Viele der Gebäude entlang der Straße sind typisch für das Wien des 19. Jahrhunderts, mit eleganten Fassaden und großzügigen Wohnräumen"}, {"kategorie": "", "text": "Entlang der Straße befinden sich mehrere Theater, darunter das renommierte [[Theater]] in der Josefstadt, eines der ältesten und bekanntesten Theater Wiens."}]'::jsonb, ''),
  ('oisa-schdrossn', 'Oisa Schdrossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Alserstraße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsstraße im 8. und 9. Wiener Gemeindebezirk ([[Josefstadt]] und [[Alsergrund]])"}, {"kategorie": "", "text": "Sie erstreckt sich vom [[Universitätsring]] im Zentrum Wiens bis zum [[Wiener]] Gürtel, wo sie in die [[Hernalser]] Hauptstraße übergeht. Die Alserstraße ist eine der Hauptverkehrsadern in diesem Teil Wiens und hat sowohl historische als auch moderne Bedeutung"}, {"kategorie": "", "text": "Entlang der Alserstraße finden sich zahlreiche historische Gebäude aus der Gründerzeit und dem 19. Jahrhundert. Viele dieser Bauten sind typische Wiener Zinshäuser, die mit reich verzierten Fassaden und hohen Decken ausgestattet sind. Einige dieser Gebäude stehen heute unter Denkmalschutz"}, {"kategorie": "", "text": "Die Alserstraße verläuft in der Nähe wichtiger medizinischer Einrichtungen, darunter das [[Allgemeine]] Krankenhaus der Stadt Wien ([[AKH]]) und die Medizinische Universität Wien"}]'::jsonb, ''),
  ('waeaeringa-schdrossn', 'Wääringa Schdrossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Währinger Straße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrs- und Geschäftsstraße in Wien, die sich vom 9. Wiener Gemeindebezirk ([[Alsergrund]]) bis in den 18. Bezirk ([[Währing]]) erstreckt. Sie verbindet das Stadtzentrum mit den westlichen Bezirken und ist eine der Hauptverkehrsadern in diesem Teil der Stadt"}, {"kategorie": "", "text": "Die Währinger Straße ist nach dem Bezirk Währing benannt, durch den sie verläuft. Der Name Währing leitet sich vom althochdeutschen Wort „wering“ ab, was so viel wie „Schutz“ bedeutet und auf die historische Schutzfunktion der Gegend hinweisen könnte"}, {"kategorie": "", "text": "Entlang der Währinger Straße finden sich zahlreiche Gebäude aus verschiedenen Epochen, insbesondere aus der Gründerzeit und dem Jugendstil. Viele der Bauten sind reich verziert und haben historische Bedeutung, während andere moderne Gebäude und Geschäftslokale die Straße prägen"}]'::jsonb, ''),
  ('heanoisa-hauptschdrossn', 'Heanoisa Hauptschdrossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Hernalser Hauptstraße', '[{"kategorie": "allg.", "text": "wichtige Verkehrs- und Einkaufsstraße im 17. Wiener Gemeindebezirk ([[Hernals]])"}, {"kategorie": "", "text": "Sie erstreckt sich vom [[Gürtel]] im Osten, wo sie an die [[Alser]] Straße anschließt, bis zum [[Elterleinplatz]] im Westen und darüber hinaus bis zur Grenze des Bezirks"}, {"kategorie": "", "text": "Die Hernalser Hauptstraße ist nach dem Bezirk Hernals benannt, durch den sie verläuft. Hernals war ursprünglich ein eigenständiges Dorf, das im 19. Jahrhundert nach Wien eingemeindet wurde. Die Straße war von Anfang an eine zentrale Verkehrsader, die das Stadtzentrum mit dem ländlichen Vorort verband"}, {"kategorie": "", "text": "Die Hernalser Hauptstraße ist geprägt von einer Mischung aus historischen Wohnhäusern, vielen davon aus der Gründerzeit, und modernen Gebäuden. Die Architektur entlang der Straße spiegelt die verschiedenen Epochen wider, in denen die Straße gewachsen ist."}]'::jsonb, ''),
  ('sigmund-freud-museum', 'Sigmund-Freud-Museum', '', '', '', 'Wiener Museen & Ausstellungsstätten', 'Sigmund-Freud-Museum', '[{"kategorie": "allg.", "text": "\"Museum in Wien, das dem Leben und Werk des Begründers der Psychoanalyse, Sigmund Freud, gewidmet ist\""}, {"kategorie": "", "text": "Es befindet sich im 9. Wiener Gemeindebezirk ([[Alsergrund]]), in der Berggasse 19, wo Freud von 1891 bis 1938 lebte und arbeitete"}, {"kategorie": "", "text": "Das Museum ist in der ehemaligen Wohnung und Praxis von Sigmund Freud untergebracht. Freud lebte hier fast 47 Jahre lang, bevor er 1938 aufgrund der politischen Verhältnisse in Österreich vor den Nationalsozialisten nach London fliehen musste"}, {"kategorie": "", "text": "Das Museum wurde 1971 eröffnet, um das Erbe Freuds zu bewahren und der Öffentlichkeit zugänglich zu machen. Es wurde von Anna Freud, der Tochter Sigmund Freuds, mitbegründet"}, {"kategorie": "", "text": "Das Sigmund-Freud-Museum zeigt eine Vielzahl von Exponaten, die Freuds Leben und Werk dokumentieren. Dazu gehören originale Möbelstücke, Dokumente, Fotografien, Manuskripte und persönliche Gegenstände von Freud. Besonders bedeutend ist das berühmte Sofa, auf dem Freuds Patienten während der psychoanalytischen Sitzungen lagen, sowie die angeschlossene Bibliothek."}]'::jsonb, ''),
  ('palaeae-coburg', 'Palää Coburg', '', '', '', 'Wiener Prachtpalais', 'Palais Coburg', '[{"kategorie": "allg.", "text": "\"historisches Stadtpalais an der [[Coburgbastei]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) und eines der bedeutendsten und prächtigsten Beispiele eines Ringstraßenpalais\""}, {"kategorie": "", "text": "Erbauung: Das Palais Coburg wurde zwischen 1839 und 1845 im Auftrag von Ferdinand Georg August von Sachsen-Coburg und Gotha erbaut, einem Mitglied des europäischen Hochadels. Es wurde im klassizistischen Stil errichtet und zeigt deutliche Anklänge an die Architektur der italienischen Renaissance"}, {"kategorie": "", "text": "Das Gebäude wurde vom Architekten Karl Schleps entworfen und ist auch als \"Sachsisches Palais\" bekannt, was auf die Herkunft der Familie Sachsen-Coburg und Gotha hinweist"}, {"kategorie": "", "text": "Die beeindruckende Fassade des Palais Coburg zeichnet sich durch eine imposante, von Säulen flankierte Loggia aus, die dem Gebäude einen palastartigen Charakter verleiht. Die Architektur ist klassizistisch geprägt, mit eleganten Proportionen und einer symmetrischen Gestaltung"}, {"kategorie": "", "text": "Die Innenräume des Palais sind reich mit Stuckaturen, Fresken und wertvollen Materialien ausgestattet. Viele der historischen Details wurden im Laufe der Zeit restauriert und erhalten"}, {"kategorie": "", "text": "Heute beherbergt das Palais Coburg ein Luxushotel, das \"Palais Coburg Residenz\", das zu den exklusivsten Hotels in Wien zählt. Besonders bekannt ist das Palais Coburg für sein Gourmet-Restaurant und seinen historischen Weinkeller, der in sechs verschiedene Bereiche unterteilt ist und Weine aus den renommiertesten Weinregionen der Welt enthält. Er zählt zu den besten und umfassendsten Weinkellern Europas."}]'::jsonb, ''),
  ('palaeae-todesco', 'Palää Todesco', '', '', '', 'Wiener Prachtpalais', 'Palais Todesco', '[{"kategorie": "allg.", "text": "bedeutendes historisches Gebäude im 1. Wiener Gemeindebezirk ([[Innere]] Stadt);  2.. Es liegt an der [[Kärntner]] Straße, einer der bekanntesten Einkaufsstraßen Wiens, in unmittelbarer Nähe zur [[Wiener]] Staatsoper"}, {"kategorie": "", "text": "Das Palais Todesco wurde in den Jahren 1861 bis 1864 erbaut. Es war eines der ersten großen Stadtpalais, die im Zuge des Ausbaus der Wiener Ringstraße errichtet wurden. Der Auftraggeber war Eduard von Todesco, ein wohlhabender Bankier und Industrieller aus der jüdischen Familie Todesco"}, {"kategorie": "", "text": "Entworfen wurde das Palais von Theophil Hansen, einem der prominentesten Architekten des [[Historismus]], der auch für andere bedeutende Wiener Gebäude wie das Parlament und das [[Palais]] Ephrussi verantwortlich war"}, {"kategorie": "", "text": "Die Fassade des Gebäudes ist reich verziert und beeindruckt durch ihre Symmetrie und die klassischen Details wie Säulen, Pilaster und Balkone"}, {"kategorie": "", "text": "Im 19. Jahrhundert war das Palais Todesco ein bedeutendes gesellschaftliches Zentrum in Wien. Hier fanden zahlreiche Bälle, Empfänge und kulturelle Veranstaltungen statt, bei denen sich die Wiener High Society traf."}]'::jsonb, ''),
  ('palaeae-liichtenschdein', 'Palää Liichtenschdein', '', '', '', 'Wiener Prachtpalais', 'Palais Liechtenstein', '[{"kategorie": "allg.", "text": "bedeutendes historisches Gebäude in Wien, das zu den prächtigsten Barockpalästen der Stadt gehört"}, {"kategorie": "", "text": "Es gibt zwei Hauptgebäude, die oft unter dem Namen \"Palais Liechtenstein\" zusammengefasst werden: das Stadtpalais Liechtenstein und das Gartenpalais Liechtenstein"}, {"kategorie": "", "text": "Das Gartenpalais liegt im 9. Wiener Gemeindebezirk ([[Alsergrund]]) und ist von einem weitläufigen Garten, dem [[Liechtensteinpark]], umgeben"}, {"kategorie": "", "text": "Es wurde im frühen 18. Jahrhundert von Fürst Johann Adam Andreas von Liechtenstein erbaut und diente der fürstlichen Familie als Sommerresidenz. Der Bau begann 1692 nach Plänen des Architekten Domenico Martinelli, und das Palais wurde 1700 fertiggestellt"}, {"kategorie": "", "text": "Das Gartenpalais ist ein herausragendes Beispiel des Barocks und beeindruckt durch seine symmetrische Gestaltung, die prachtvollen Fassaden und die aufwendigen Innenräume. Es beherbergt eine bedeutende Kunstsammlung, die \"LIECHTENSTEIN Princely Collections\", mit Meisterwerken europäischer Kunst vom Frühmittelalter bis zur Renaissance und darüber hinaus"}, {"kategorie": "", "text": "Das Stadtpalais liegt im 1. Wiener Gemeindebezirk an der [[Bankgasse]], nahe der [[Freyung]]"}, {"kategorie": "", "text": "Das Stadtpalais wurde ebenfalls für die Familie Liechtenstein errichtet und diente als deren Stadtresidenz. Es ist eines der frühesten und bedeutendsten barocken Stadtpaläste in Wien, dessen Bau 1692 begann"}, {"kategorie": "", "text": "Das Palais besticht durch seine prachtvolle barocke Fassade und die luxuriöse Innenausstattung. Es wurde mehrfach umgebaut, wobei es seine ursprüngliche barocke Pracht bewahrt hat."}]'::jsonb, ''),
  ('oigemeines-kraunknhaus-wiin', 'Oigemeines Kraunknhaus Wiin', '', '', '', 'Wiener Gemeindebauten', 'Allgemeines Krankenhaus Wien', '[{"kategorie": "allg.", "text": "\"eines der größten und renommiertesten Krankenhäuser Europas\", kurz [[AKH]] genannt"}, {"kategorie": "", "text": "Es befindet sich im 9. Wiener Gemeindebezirk ([[Alsergrund]]) und ist sowohl ein zentrales medizinisches Versorgungszentrum als auch ein bedeutender Forschungs- und Ausbildungsstandort"}, {"kategorie": "", "text": "Das AKH Wien wurde 1693 gegründet und hat eine lange Tradition als führende medizinische Einrichtung in Wien und Europa. Ursprünglich als Armenspital errichtet, hat es sich im Laufe der Jahrhunderte zu einem modernen Universitätsklinikum entwickelt"}, {"kategorie": "", "text": "Das heutige Gebäude des AKH Wien wurde zwischen 1964 und 1994 errichtet und zählt zu den größten Krankenhausbauten der Welt mit mehreren Hochhäusern und einem weitläufigen Campus. Das zentrale Gebäude ist das Hochhaus des AKH, ein markantes Bauwerk, das die Skyline von [[Alsergrund]] prägt"}]'::jsonb, ''),
  ('oides-akh', 'Oides AKH', '', '', '', 'Wiener Gemeindebauten', 'Altes AKH', '[{"kategorie": "wörtlich, Kurzform für", "text": "\"Altes Allgemeines Krankenhaus Wien\" - historischer Gebäudekomplex im 9. Wiener Gemeindebezirk ([[Alsergrund]]), der heute als Universitätscampus der [[Universität]] Wien genutzt wird. Es war ursprünglich das zentrale Krankenhaus der Stadt Wien und spielte eine bedeutende Rolle in der medizinischen Geschichte Österreichs und Europas"}, {"kategorie": "", "text": "Das Alte AKH wurde 1693 unter Kaiser Leopold I. als Großarmenhaus gegründet und diente zunächst der Unterbringung armer und kranker Menschen. Im Laufe der Zeit entwickelte es sich zu einem bedeutenden Krankenhaus, das als Allgemeines Krankenhaus bekannt wurde"}, {"kategorie": "", "text": "Das Alte AKH war eng mit der Geschichte der Medizin in Wien verbunden. Hier arbeiteten und lehrten einige der bekanntesten Ärzte und Wissenschaftler, darunter Ignaz Semmelweis, der als „Retter der Mütter“ für seine Entdeckung der Ursachen des Kindbettfiebers bekannt ist"}, {"kategorie": "", "text": "Der Gebäudekomplex des Alten AKH ist geprägt von historischen Bauten aus verschiedenen Epochen. Die Architektur spiegelt die Entwicklung des Krankenhauses über die Jahrhunderte wider, von barocken und klassizistischen Bauwerken bis hin zu Bauten aus dem 19. Jahrhundert"}, {"kategorie": "", "text": "Ein markantes Bauwerk ist der [[Narrenturm]], ein rundes Gebäude, das 1784 als erstes speziell für psychisch kranke Menschen errichtetes Krankenhausgebäude in Europa erbaut wurde. Heute beherbergt es das [[Pathologisch-anatomische]] Bundesmuseum"}, {"kategorie": "", "text": "In den 1990er Jahren wurde das Krankenhaus an seinen heutigen Standort, das neue [[AKH]] Wien, verlegt. Der historische Gebäudekomplex des Alten AKH wurde anschließend renoviert und zum Campus der Universität Wien umgebaut."}]'::jsonb, ''),
  ('schloss-hetznduaf', 'Schloss Hetznduaf', '', '', '', 'Wiener Prachtpalais', 'Schloss Hetzendorf', '[{"kategorie": "allg.", "text": "\"barockes Schloss im 12. Wiener Gemeindebezirk ([[Meidling]]), bekannt für seine prächtige Architektur und historische Bedeutung sowie seine heutige Nutzung als Modeschule der Stadt Wien\""}, {"kategorie": "hist.", "text": "Das Schloss Hetzendorf wurde im 17. Jahrhundert erbaut und diente ursprünglich als Landhaus für Wiener Adelige. Im 18. Jahrhundert wurde es unter Kaiserin Maria Theresia zu einem barocken Schloss ausgebaut. Im Laufe seiner Geschichte wurde das Schloss von verschiedenen adeligen Familien bewohnt und diente zeitweise auch als kaiserliche Sommerresidenz"}, {"kategorie": "Architektur", "text": "Das Schloss ist ein eindrucksvolles Beispiel barocker Architektur, das von Johann Lucas von Hildebrandt umgestaltet wurde. Es zeichnet sich durch seine symmetrische Fassadengestaltung und die prächtigen Innenräume aus. Im Schloss befinden sich repräsentative Räume wie der Festsaal, der mit aufwendigen Stuckarbeiten und Fresken verziert ist"}, {"kategorie": "Gartenanlage", "text": "Zum Schloss gehört eine großzügige Gartenanlage, die im barocken Stil angelegt wurde. Der Schlosspark ist ein Beispiel für die Gartenkunst des 18. Jahrhunderts und lädt zum Spazieren und Verweilen ein. Der Garten wurde ursprünglich im französischen Stil angelegt, später aber teilweise in einen englischen Landschaftsgarten umgestaltet"}, {"kategorie": "Modeschule", "text": "Seit 1947 ist Schloss Hetzendorf Sitz der Modeschule der Stadt Wien, die eine der renommiertesten Bildungseinrichtungen für Mode und Design in Österreich ist. Hier werden Schüler in den Bereichen Modedesign, Schneiderei und Textiltechnik ausgebildet."}]'::jsonb, ''),
  ('meidlinga-hauptschdrossn', 'Meidlinga Hauptschdrossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Meidlinger Hauptstraße', '[{"kategorie": "allg.", "text": "zentrale Einkaufs- und Flaniermeile im 12. Wiener Gemeindebezirk ([[Meidling]])"}, {"kategorie": "", "text": "Die Meidlinger Hauptstraße verläuft in Nord-Süd-Richtung durch den Bezirk Meidling und erstreckt sich vom Margaretengürtel im Norden bis zur Breitenfurter Straße im Süden"}, {"kategorie": "", "text": "Ein zentraler Teil der Meidlinger Hauptstraße ist als Fußgängerzone ausgewiesen. Dieser Abschnitt ist das Herzstück der Straße und ein beliebtes Einkaufsziel für die Anwohner"}, {"kategorie": "", "text": "Entlang der Straße befinden sich zahlreiche Geschäfte, Boutiquen, Supermärkte, Restaurants und Cafés, die ein breites Spektrum an Waren und Dienstleistungen anbieten. Die Fußgängerzone lädt zum Flanieren und Verweilen ein und ist ein sozialer Treffpunkt für Menschen aus dem Bezirk"}]'::jsonb, ''),
  ('aum-schoepfweak', 'Aum Schöpfweak', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Am Schöpfwerk', '[{"kategorie": "allg.", "text": "große Wohnanlage im 12. Wiener Gemeindebezirk ([[Meidling]])"}, {"kategorie": "", "text": "Die Siedlung wurde in den 1970er Jahren als groß angelegtes Wohnbauprojekt errichtet. Ziel war es, dringend benötigten Wohnraum für die wachsende Bevölkerung Wiens zu schaffen"}, {"kategorie": "Architektur", "text": "Die Architektur \"Am Schöpfwerk\" ist geprägt von modernen, funktionalen Gebäuden, die in einem einheitlichen Stil gestaltet sind. Die Anlage umfasst mehrere Wohnblöcke, die durch Grünflächen, Innenhöfe und Fußwege miteinander verbunden sind"}, {"kategorie": "", "text": "\"Am Schöpfwerk\" bietet Wohnraum für mehrere Tausend Menschen. Die Anlage besteht aus verschiedenen Wohnungstypen, die sowohl für Familien als auch für Singles und ältere Menschen geeignet sind"}, {"kategorie": "", "text": "Die Siedlung ist bekannt für ihre soziale Vielfalt und hat im Laufe der Jahre verschiedene Herausforderungen in Bezug auf soziale Integration und Stadtentwicklung erlebt. Dennoch bleibt sie ein wichtiges Beispiel für den sozialen Wohnungsbau in Wien."}]'::jsonb, ''),
  ('wuehemsduafa-park', 'Wühemsduafa Park', '', '', '', 'Wiener Parks und Parkanlagen', 'Wilhelmsdorfer Park', '[{"kategorie": "allg.", "text": "Grünanlage im 12. Wiener Gemeindebezirk ([[Meidling]]), zentral gelegen in der Nähe der Wilhelmsdorfer Straße und der [[Meidlinger]] Hauptstraße"}, {"kategorie": "", "text": "Der Park ist gut erreichbar und eingebettet in ein dicht bebautes Wohngebiet, was ihn zu einem wichtigen Naherholungsgebiet für die Anwohner macht"}, {"kategorie": "", "text": "Der Park wurde im 20. Jahrhundert angelegt, um den Bewohnern von Meidling eine Grünfläche zur Verfügung zu stellen. Er trägt den Namen des angrenzenden Wilhelmsdorfs, einem Teil des Bezirks, der im 19. Jahrhundert urbanisiert wurde."}]'::jsonb, ''),
  ('meidlinga-kasean', 'Meidlinga Kasean', '', '', '', 'Wiener Gemeindebauten', 'Meidlinger Kaserne', '[{"kategorie": "hist.", "text": "einst eine bedeutende militärische Anlage im 12. Wiener Gemeindebezirk ([[Meidling]])"}, {"kategorie": "", "text": "Die Meidlinger Kaserne wurde im 19. Jahrhundert errichtet, um die wachsende Garnison von Wien unterzubringen. Sie war Teil des Ausbaus der militärischen Infrastruktur der Stadt und sollte die Verteidigungsfähigkeit Wiens stärken"}, {"kategorie": "", "text": "Die Gebäude der Meidlinger Kaserne waren typisch für militärische Bauten des 19. Jahrhunderts: solide, funktional und mit einem starken Fokus auf Sicherheit und Effizienz. Die Anlage umfasste Kasernenblöcke, Übungsgelände, Lagerhäuser und Verwaltungsgebäude"}, {"kategorie": "", "text": "Die Meidlinger Kaserne wurde nach ihrer Schließung teilweise abgerissen, und das Gelände wurde für andere städtische Zwecke umgenutzt. Heute sich neben der Flugpolizei noch andere Dienststellen des Innenministeriums in der Kaserne eingerichtet, wie das Bundesamt für Korruptionsbekämpfung und Korruptionsprävention (BAK). Auch befindet sich im Kasernengebäude, mit einem separaten Eingang zur Hohenbergstraße, das Stadtpolizeikommando Meidling sowie eine Polizeiinspektion."}]'::jsonb, ''),
  ('klimt-villa', 'Klimt-Villa', '', '', '', 'Wiener Museen & Ausstellungsstätten', 'Klimt-Villa', '[{"kategorie": "allg.", "text": "ehemaliges Atelier von Gustav Klimt im 13. Wiener Gemeindebezirk Hietzing. Es handelt sich um ein spätklassizistisches Gebäude, in dem Klimt von 1911 bis zu seinem Tod 1918 arbeitete (Feldmühlgasse 11, 1130 Wien, Bezirk: [[Hietzing]], nahe dem [[Schlosspark]] Schönbrunn)"}, {"kategorie": "", "text": "Die Villa war der letzte Arbeitsort Gustav Klimts. Viele seiner späten Werke, darunter unvollendete Gemälde wie „Die Braut“ oder „Adam und Eva“, entstanden hier"}, {"kategorie": "", "text": "Seit der Restaurierung ist die Klimt-Villa öffentlich zugänglich. Sie dient als Museum, Gedenkstätte und Forschungszentrum. Die rekonstruierte Atelierausstattung ermöglicht es Besucher:innen, einen authentischen Eindruck von Klimts Arbeitsumgebung zu gewinnen."}]'::jsonb, ''),
  ('eanst-fuchs-villa', 'Eanst-Fuchs-Villa', '', '', '', 'Wiener Museen & Ausstellungsstätten', 'Ernst-Fuchs-Villa', '[{"kategorie": "allg.", "text": "prachtvolle historische Villa in Wien, die vom österreichischen Maler, Bildhauer, Architekten und Mitbegründer der Wiener Schule des Phantastischen Realismus Ernst Fuchs (1930–2015) bewohnt und umfassend umgestaltet wurde. Heute ist sie ein Museum und Zentrum für sein Lebenswerk – das Ernst Fuchs Museum (Hüttelbergstraße 26, 1140 Wien, Bezirk: [[Penzing]], Wienerwaldgebiet, am Stadtrand)"}, {"kategorie": "", "text": "Die Villa wurde 1888 vom berühmten Jugendstil-Architekten Otto Wagner für sich selbst entworfen und erbaut. Stilistisch vereint sie Merkmale des [[Historismus]] und frühen [[Jugendstils]]. Sie wird daher auch als „Otto-Wagner-Villa I“ bezeichnet (nicht zu verwechseln mit der [[Otto-Wagner-Villa]] II in der Döblergasse)"}, {"kategorie": "", "text": "Ernst Fuchs erwarb die stark renovierungsbedürftige Villa in den 1970er-Jahren. Er restaurierte und gestaltete sie mit seinem unverkennbaren phantastischen Stil um, einschließlich prunkvoller Malereien, Mosaike, Skulpturen und Möbelentwürfe. Die Innenräume wurden zu einer begehbaren Gesamtkomposition seines künstlerischen Schaffens"}, {"kategorie": "", "text": "Die Villa ist heute ein öffentlich zugängliches Museum mit Gemälden, Zeichnungen und Skulpturen von Ernst Fuchs, Ausstellungen über den Phantastischen Realismus, sowie den von Fuchs gestalteten Räumen und Möbeln (auch Werke seiner Schüler oder Zeitgenossen werden gelegentlich ausgestellt)."}]'::jsonb, ''),
  ('otto-wagna-villa', 'Otto-Wagna-Villa', '', '', '', 'Wiener Museen & Ausstellungsstätten', 'Otto-Wagner-Villa', '[{"kategorie": "allg.", "text": "\"Otto Wagner Villa I\" und \"Otto Wagner Villa II\""}, {"kategorie": "", "text": "Der Begriff „Otto-Wagner-Villa“ bezeichnet zwei architektonisch und historisch bedeutende Villen in Wien, die vom weltberühmten österreichischen Architekten Otto Wagner (1841–1918) entworfen wurden. Beide Villen stehen in enger Verbindung zu Wagners Lebenswerk und gelten als wichtige Beispiele des Übergangs vom Historismus zum Jugendstil"}, {"kategorie": "", "text": "Otto-Wagner-Villa I (1888) – heute: [[Ernst-Fuchs-Villa]],\nHüttelbergstraße 26, 1140 Wien Bezirk [[Penzing]], Bauzeit: 1886–1888, Stil: [[Späthistorismus]] mit frühen [[Jugendstilelementen]], Zweck: als Privatvilla Otto Wagners entworfen und genutzt. Besonderheiten: Später vom Künstler Ernst Fuchs erworben (1972), heute: [[Ernst]] Fuchs Museum, wurde von Fuchs im Stil des Phantastischen Realismus umgestaltet. Diese Villa wird umgangssprachlich oft als \"die Otto-Wagner-Villa\" bezeichnet, da sie die erste war, die er für sich selbst plante"}, {"kategorie": "", "text": "Otto-Wagner-Villa II: (1912–1913), Döblergasse 4, 1140 Wien (ebenfalls in [[Penzing]]), Bauzeit: 1912–1913, Stil: Spätjugendstil mit rationalistischen Elementen, Zweck: zweite Privatresidenz Wagners im Alter, nach dem Tod seiner Frau, Besonderheiten: deutlich reduzierter und moderner als die erste Villa, zeigt Wagners spätes architektonisches Denken, heute in Privatbesitz (daher nicht öffentlich zugänglich)"}, {"kategorie": "", "text": "Architektonisch sind beide Villen Meilensteine der [[Wiener]] Moderne und des [[Jugendstils]], kulturell spiegeln sie die Lebensphasen Otto Wagners wider, und historisch belegen sie den Übergang von der Prunkarchitektur zu funktionaler Moderne."}]'::jsonb, ''),
  ('otto-wagna-kiachn-aum-schdaahof', 'Otto-Wagna-Kiachn aum Schdaahof', '', '', '', 'Wiener Kirchen & Gotteshäuser', 'Otto-Wagner-Kirche am Steinhof', '[{"kategorie": "allg.", "text": "\"bedeutende Jugendstilkirche in Wien, die vom berühmten österreichischen Architekten Otto Wagner entworfen wurde\" (auch bekannt als \"Kirche zum Heiligen Leopold\")"}, {"kategorie": "", "text": "Sie befindet sich im 14. Wiener Gemeindebezirk ([[Penzing]]) auf dem Gelände des Sozialmedizinischen Zentrums Baumgartner Höhe, besser bekannt als Otto-Wagner-Spital"}, {"kategorie": "", "text": "Die Kirche wurde zwischen 1904 und 1907 im Rahmen der Errichtung der Nervenheilanstalt am Steinhof (heute Otto-Wagner-Spital) erbaut. Sie war von Anfang an als Anstaltskirche konzipiert und sollte den Bedürfnissen der Patienten und des medizinischen Personals gerecht werden"}, {"kategorie": "", "text": "Die Kirche ist ein Beispiel für die klare, funktionale Gestaltung des Jugendstils, kombiniert mit prachtvollen dekorativen Elementen. Die Fassade ist weiß verputzt und wird durch goldene Kuppeln und Verzierungen akzentuiert. Der zentrale Teil des Bauwerks wird von einer großen, vergoldeten Kuppel gekrönt, die ein markantes Wahrzeichen der Kirche ist"}, {"kategorie": "", "text": "Die Fassade der Kirche ist mit goldenen Verzierungen und Symbolen geschmückt, darunter Engelsfiguren, die den Jugendstilcharakter unterstreichen. Über dem Eingang befinden sich Mosaiken, die Szenen aus dem Leben des Heiligen Leopold, dem Schutzpatron der Kirche, darstellen"}, {"kategorie": "", "text": "Besondere Aufmerksamkeit wurde auf die Anpassung der Kirche an die Bedürfnisse der Patienten gelegt: So sind die Kirchenbänke ohne scharfe Kanten gestaltet, es gibt breite Zugänge und spezielle Sitze für Rollstuhlfahrer."}]'::jsonb, ''),
  ('rudoifsheim-fuenfhaus', 'Rudoifsheim-Fünfhaus', '', '', '', 'Wiener Prachtpalais und Prunkbauten', 'Rudolfsheim-Fünfhaus', '[{"kategorie": "wörtlich", "text": "\"Wien-Rudolfsheim/Fünfhaus\""}, {"kategorie": "", "text": "\"der fünfzehnte [[Hieb]]\" (= 15. Wiener Gemeindebezirk)"}, {"kategorie": "", "text": "Rudolfsheim-Fünfhaus liegt im Westen Wiens und grenzt im Osten an den 6. Bezirk ([[Mariahilf]]) und den 7. Bezirk ([[Neubau]]), im Norden an den 14. Bezirk ([[Penzing]]), im Westen an den 16. Bezirk ([[Ottakring]]) und im Süden an den 12. Bezirk ([[Meidling]])"}, {"kategorie": "", "text": "Der Bezirk entstand 1892 durch die Zusammenlegung der ehemals eigenständigen Vororte Rudolfsheim, Fünfhaus und Sechshaus. Diese Vororte wurden ursprünglich als Arbeiterviertel gegründet und entwickelten sich im 19. Jahrhundert zu dicht besiedelten Stadtteilen"}, {"kategorie": "", "text": "Rudolfsheim-Fünfhaus war in der Vergangenheit stark von der Industrie und den Eisenbahnanlagen geprägt. Heute ist der Bezirk durch seine Urbanität und multikulturelle Prägung gekennzeichnet"}, {"kategorie": "", "text": "Rudolfsheim-Fünfhaus ist einer der bevölkerungsreichsten Bezirke Wiens. Viele Menschen mit Migrationshintergrund leben in diesem Bezirk, was zu einer großen kulturellen Vielfalt beiträgt"}, {"kategorie": "", "text": "Der Bezirk ist bekannt für seine lebendige Kulturszene, darunter das [[Westbahntheater]], die [[Galerie]] Westlicht und zahlreiche kleine Theater, Musiklokale und Kulturvereine. Das [[Reithoffer-Areal]], ein ehemaliges Fabrikgelände, ist heute ein Kulturzentrum und Treffpunkt für Künstler und Kreative"}]'::jsonb, ''),
  ('galerii-westlicht', 'Galerii Westlicht', '', '', '', 'Wiener Museen & Ausstellungsstätten', 'Galerie Westlicht', '[{"kategorie": "allg.", "text": "international renommiertes Fotografiezentrum in Wien, das als Ausstellungsraum, Museum und kulturelle Plattform für historische und zeitgenössische Fotografie dient. Es gilt als einer der wichtigsten Orte für Fotokunst in Österreich und im deutschsprachigen Raum und wurde 2001 von Peter Coeln gegründet (Adresse: Westbahnstraße 40, 1070 Wien, Bezirk: [[Neubau]])"}, {"kategorie": "", "text": "Die Galerie Westlicht ist in einer ehemaligen Glasmanufaktur untergebracht (loftartiger Ausstellungsraum mit industriellem Charme, Kombination aus Fotogalerie, Kamera-Museum und Eventlocation)"}, {"kategorie": "", "text": "Sie präsentiert bedeutende internationale und österreichische Fotokunst sowie eine historische Sammlung von Fotokameras und -technik. Gleichzeitig fördert sie den Dialog zwischen klassischer Fotografie und digitaler Bildkultur und dient auch als Plattform für den Nachwuchs, aber auch für die Präsentation etablierter Künstler:innen."}]'::jsonb, ''),
  ('reithoffer-areal', 'Reithoffer-Areal', '', '', '', 'Wiener Gemeindebauten', 'Reithoffer-Areal', '[{"kategorie": "allg.", "text": "\"ehemaliges Industrie- und Fabrikgelände im 15. Wiener Gemeindebezirk Rudolfsheim-Fünfhaus (zwischen [[Sechshauser]] Straße, [[Mariahilfer]] Straße und [[Reithofferpark]]), das heute als städtisches Entwicklungsgebiet mit sozialen, kulturellen und wohnbaulichen Funktionen genutzt wird\". Es ist nach der traditionsreichen Fabrik Reithoffer benannt, die hier im 19. und 20. Jahrhundert eine zentrale Rolle in der Wiener Industrialisierung spielte"}, {"kategorie": "", "text": "Die Reithoffer-Fabrik (ehemals Vereinigte Wiener Gummiwaaren-Fabriken) wurde im 19. Jahrhundert durch die Unternehmerfamilie Reithoffer gegründet und war einst eine der ersten großen Gummiwarenfabriken Europas. Sie war bedeutend für die Industriegeschichte Wiens und den Arbeiterbezirk Fünfhaus, bis sie in den 1970er/80er Jahren stillgelegt wurde und in einen Dornröschenschlaf verfiel"}, {"kategorie": "", "text": "Ab den 1990er-Jahren wurde dann eine Initiative zur sozialen und kulturellen Wiederbelebung des Areals gestartet, deren Ziel einserseits der Erhalt einiger Industriebauten (z. B. Klinkerfassaden) im Sinne des „Industrie-Denkmalschutzes“ und andererseits die Einbindung in das städtische Stadterneuerungsprogramm waren"}, {"kategorie": "", "text": "Heute ist das Areal geprägt durch den [[Reithofferpark]] (öffentlicher Park inmitten des Areals mit Sportflächen, Kinderspielplätzen und Erholungszonen, was als Symbol für die „Zurückeroberung“ von Industrieflächen durch die Bevölkerung gilt), ein Schulzentrum mit Mittelschulen und Berufsausbildungseinrichtungen, Ausstellungsflächen und Räume für Kinstschaffende, sowie Kleingewerbe & Initiativen für lokale Nahversorgung."}]'::jsonb, ''),
  ('reithoffer-park', 'Reithoffer-Park', '', '', '', 'Wiener Parks und Parkanlagen', 'Reithoffer-Park', '[{"kategorie": "allg.", "text": "öffentlicher Park im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]]). Er befindet sich auf einem Teil des ehemaligen Industrieareals der Reithoffer-Gummiwarenfabrik, das in der zweiten Hälfte des 20. Jahrhunderts in eine urbane Grün- und Erholungsfläche umgewandelt wurde. Heute ist der Reithofferpark ein wichtiger Naherholungsraum und sozialer Treffpunkt im dicht besiedelten innerstädtischen Gebiet"}, {"kategorie": "", "text": "Benannt ist der Park nach der Reithoffer-Fabrik, einem bedeutenden Gummi- und Gummiwarenhersteller des 19. Jahrhunderts. Die ehemalige Fabrikhalle stand direkt auf dem heutigen Parkgelände. Die Umgestaltung des Geländes war Teil der Stadterneuerung in Rudolfsheim-Fünfhaus"}, {"kategorie": "", "text": "Der Park hat eine Fläche von ca. 13.000 m² (1,3 Hektar), wurde in den 80-er Jahren eröffnet (im Zuge der Umgestaltung des ehemaligen Industrieareals) und ist die wichtigste öffentliche Grünfläche im innerstädtischen Teil von Rudolfsheim-Fünfhaus"}]'::jsonb, ''),
  ('ottakringa-schdrossn', 'Ottakringa Schdrossn', '', '', '', 'Wiener Gassen, Straßen & Plätze', 'Ottakringer Straße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrs- und Einkaufsstraße im 16. Wiener Gemeindebezirk ([[Ottakring]]), oft auch \"Ottakringer Hauptstraße\" genannt)"}, {"kategorie": "", "text": "Sie beginnt im Osten an der Grenze zum 17. Bezirk ([[Hernals]]) und führt in westlicher Richtung durch Ottakring bis zum [[Wilhelminenberg]], einem beliebten Ausflugsziel am westlichen Stadtrand von Wien"}, {"kategorie": "", "text": "Die Ottakringer Straße entwickelte sich im Laufe des 19. Jahrhunderts zu einer wichtigen Verkehrsachse. Ursprünglich war sie eine ländliche Straße, die die Vorstadt Ottakring mit dem Stadtzentrum verband. Mit der Industrialisierung und dem Bevölkerungswachstum wuchs ihre Bedeutung als zentrale Verbindungsstraße und Handelsweg"}, {"kategorie": "", "text": "Der Name der Straße leitet sich vom ehemaligen Vorort Ottakring ab, der 1892 als eigenständiger Bezirk in die Stadt Wien eingegliedert wurde"}]'::jsonb, ''),
  ('ottakringa-brauarei', 'Ottakringa Brauarei', '', '', '', 'Wiener Gemeindebauten', 'Ottakringer Brauerei', '[{"kategorie": "allg.", "text": "eine der ältesten und bekanntesten Brauereien in Wien, welche im 16. Wiener Gemeindebezirk ([[Ottakring]]) beheimatet und ein bedeutendes Wahrzeichen des Bezirks sowie ein wichtiger Teil der Wiener Brautradition ist"}, {"kategorie": "", "text": "Die Ottakringer Brauerei wurde 1837 gegründet, als der Unternehmer Heinrich Plank die ersten Brauanlagen in Ottakring errichtete. Seit ihrer Gründung hat sich die Brauerei stetig weiterentwickelt und ist heute die letzte große, privat geführte Brauerei in Wien"}, {"kategorie": "", "text": "Die Ottakringer Brauerei erstreckt sich über ein großes Areal in Ottakring und umfasst mehrere historische und moderne Gebäude. Das Hauptgebäude der Brauerei ist ein markantes Beispiel für Industriearchitektur des 19. Jahrhunderts"}, {"kategorie": "", "text": "Die Ottakringer Brauerei ist nicht nur für ihre Bierproduktion bekannt, sondern auch als Veranstaltungsort für eine Vielzahl von kulturellen und gesellschaftlichen Events."}]'::jsonb, ''),
  ('schloss-wuehaeminenbeag', 'Schloss Wühäminenbeag', '', '', '', 'Wiener Prachtpalais', 'Schloss Wilhelminenberg', '[{"kategorie": "allg.", "text": "historisches Schloss im 16. Wiener Gemeindebezirk ([[Ottakring]])"}, {"kategorie": "", "text": "Es liegt auf einer Anhöhe des [[Wilhelminenbergs]] und bietet eine beeindruckende Aussicht über Wien. Heute wird das Schloss als Hotel und Veranstaltungsort genutzt und ist bekannt für seine malerische Lage und seine historische Bedeutung"}, {"kategorie": "", "text": "Das Schloss Wilhelminenberg wurde zwischen 1903 und 1908 im neobarocken Stil erbaut. Es wurde von Erzherzogin Wilhelmine Amalie, einer Tochter von [[Kaiser]] Leopold II., in Auftrag gegeben und nach ihr benannt. Es diente ursprünglich als Jagdschloss und Sommerresidenz für den österreichischen Adel"}, {"kategorie": "Architektur", "text": "Das Schloss umfasst mehrere Flügel, die um einen zentralen Hof angeordnet sind. Der Haupteingang ist durch eine breite Treppe und eine imposante Säulenhalle gekennzeichnet. Es ist im neobarocken Stil gestaltet und zeichnet sich durch seine symmetrische Fassade, dekorative Stuckarbeiten und ein repräsentatives Erscheinungsbild aus. Die Architektur spiegelt den Stil und die Eleganz der späten Habsburgerzeit wider"}, {"kategorie": "", "text": "Das Schloss liegt auf dem [[Wilhelminenberg]], einer Anhöhe im Westen von Ottakring, und bietet einen atemberaubenden Panoramablick über Wien. Die Lage inmitten des [[Wienerwaldes]] macht das Schloss zu einem beliebten Ausflugsziel für Erholungssuchende."}]'::jsonb, ''),
  ('schloss-neuwoidegg', 'Schloss Neuwoidegg', '', '', '', 'Wiener Prachtpalais', 'Schloss Neuwaldegg', '[{"kategorie": "allg.", "text": "bedeutendes historisches Gebäude im 17. Wiener Gemeindebezirk ([[Hernals]]), am Rande des [[Wienerwalds]]"}, {"kategorie": "", "text": "Der Bau des Schlosses geht auf das Jahr 1697 zurück, als Graf Theodor von Strattmann, ein bedeutender österreichischer Staatsmann und Diplomat, das Anwesen errichten ließ. Graf Strattmann war während der Regentschaft von Kaiser Leopold I. als Reichsvizekanzler tätig und spielte eine wichtige Rolle in den politischen Angelegenheiten des Habsburgerreiches. Sein Ziel war es, ein repräsentatives Anwesen zu schaffen, das seine Stellung und seinen Reichtum widerspiegelte"}, {"kategorie": "", "text": "Nach dem Tod von Graf Strattmann wechselte das Schloss mehrmals den Besitzer. Einer der bekanntesten Eigentümer war die Familie Hoyos, die das Anwesen im 18. Jahrhundert erwarb. Besonders unter Graf Karl von Hoyos, der das Schloss 1765 erbte, erlebte Neuwaldegg eine Blütezeit. Karl von Hoyos war es, der den Schlosspark im Stil englischer Landschaftsgärten umgestalten ließ und das Anwesen in einen Ort der Ruhe und Erholung verwandelte. Der Gartenarchitekt Jean Trehet, ein Schüler des berühmten André Le Nôtre, war für die Gestaltung des Parks verantwortlich"}, {"kategorie": "", "text": "Das Schlossgebäude selbst ist ein beeindruckendes Beispiel barocker Architektur. Es zeichnet sich durch seine symmetrische Fassade und die typischen Gestaltungselemente dieser Epoche aus, wie etwa prächtige Stuckarbeiten, Marmorsäulen und eine kunstvolle Innenausstattung. Das Hauptgebäude ist von zwei Seitenflügeln flankiert, die einen großen Ehrenhof umschließen"}, {"kategorie": "", "text": "Der Schlosspark ist ein wahres Highlight und erstreckt sich über eine Fläche von etwa 50 Hektar. Er wurde im späten 18. Jahrhundert im Stil eines französischen Gartens angelegt, mit einer Mischung aus geometrischen Mustern, prachtvollen Alleen und malerischen Wasserflächen. Später wurde der Park im englischen Landschaftsstil umgestaltet, was ihm ein romantischeres und natürlicheres Aussehen verlieh. Der Park umfasst künstliche Ruinen, eine Orangerie, sowie zahlreiche exotische Bäume und Pflanzen, die im 18. und 19. Jahrhundert aus verschiedenen Teilen der Welt importiert wurden"}, {"kategorie": "", "text": "Heute befindet sich Schloss Neuwaldegg in privatem Besitz und wird für diverse Veranstaltungen vermietet. Die prachtvolle Kulisse und der historische Charme machen es zu einem beliebten Ort für exklusive Events. Der Park ist der Öffentlichkeit zugänglich und ein geschätzter Erholungsraum für die Wiener Bevölkerung, der besonders an Wochenenden und in den Sommermonaten viele Besucher anzieht."}]'::jsonb, ''),
  ('pfoakiachn-doanboch', 'Pfoakiachn Doanboch', '', '', '', 'Wiener Kirchen & Gotteshäuser', 'Pfarrkirche Dornbach', '[{"kategorie": "allg.", "text": "römisch-katholische Kirche im Wiener Stadtteil [[Dornbach]], der zum 17. Wiener Gemeindebezirk ([[Hernals]]) gehört"}, {"kategorie": "", "text": "Die heutige Pfarrkirche Dornbach wurde im neugotischen Stil errichtet und ist ein Beispiel für den gotischen [[Historismus]], der im 19. Jahrhundert in Wien und ganz Europa populär war. Der Bau der Kirche begann 1826 und wurde 1830 abgeschlossen. Der Entwurf der Kirche stammt von dem Architekten Josef Kastan, der für seine Arbeiten im neugotischen Stil bekannt ist"}, {"kategorie": "", "text": "Die Kirche hat eine markante, turmlose Fassade mit einem zentralen Giebel und großen, spitzbogigen Fenstern, die typisch für den neugotischen Stil sind. Das Innere der Kirche ist ebenfalls im gotischen Stil gestaltet, mit einem hohen, hellen Kirchenschiff, das von Säulen und [[Rippengewölben]] getragen wird. Besonders bemerkenswert ist der reich verzierte Hochaltar, der ebenfalls im neugotischen Stil gehalten ist und die architektonische Einheit des Kirchenraums unterstreicht"}, {"kategorie": "", "text": "Die Geschichte der Pfarrgemeinde Dornbach reicht weiter zurück als das heutige Kirchengebäude. Bereits im Mittelalter existierte in Dornbach eine kleinere Kirche, die dem Heiligen Jakob geweiht war. Mit der zunehmenden Bevölkerung im 19. Jahrhundert und der wachsenden Bedeutung Dornbachs als Wohngebiet für wohlhabende Bürger entschied man sich, die alte Kirche durch einen größeren, repräsentativeren Bau zu ersetzen, was schließlich zur Errichtung der heutigen Pfarrkirche führte."}]'::jsonb, ''),
  ('friidhof-doanboch', 'Friidhof Doanboch', '', '', '', 'Wiener Friedhöfe & Gottesacker', 'Friedhof Dornbach', '[{"kategorie": "allg.", "text": "historischer Friedhof im Wiener Stadtteil [[Dornbach]], der zum 17. Wiener Gemeindebezirk ([[Hernals]]) gehört"}, {"kategorie": "", "text": "Er liegt malerisch am Rande des Wienerwalds und ist sowohl ein Ort des Gedenkens als auch ein bedeutendes Kulturdenkmal"}, {"kategorie": "", "text": "Der Friedhof Dornbach wurde im Jahr 1783 angelegt und ist einer der ältesten Friedhöfe Wiens. Er entstand in einer Zeit, in der aufgrund der hygienischen Bedingungen und der zunehmenden Bevölkerung neue Friedhöfe außerhalb der Stadtgrenzen angelegt werden mussten"}, {"kategorie": "", "text": "Auf dem Friedhof wurden zahlreiche Persönlichkeiten bestattet, darunter auch Mitglieder bedeutender Wiener Familien und bekannte Künstler. Zu den bekanntesten zählt der österreichische Komponist und Militärkapellmeister Carl Michael Ziehrer (1843–1922), der als einer der bedeutendsten Vertreter der Wiener Musiktradition gilt und oft als Konkurrent von Johann Strauss Sohn angesehen wurde"}, {"kategorie": "", "text": "Der Friedhof Dornbach ist von seiner ursprünglichen Größe und Struktur her relativ klein, was ihm einen intimen und ruhigen Charakter verleiht. Die Anlage ist von einer schlichten Friedhofsmauer umgeben und umfasst zahlreiche historische Grabstätten, die kunstvoll gestaltet sind. Viele dieser Grabstätten stammen aus dem 19. und frühen 20. Jahrhundert und sind mit aufwendigen Skulpturen, schmiedeeisernen Gittern und kunstvollen Inschriften versehen."}]'::jsonb, ''),
  ('pfoakiachn-obalaa', 'Pfoakiachn Obalaa', '', '', '', 'Wiener Kirchen & Gotteshäuser', 'Pfarrkirche Oberlaa', '[{"kategorie": "wörtlich", "text": "\"Kirche zum heiligen Ägydius\" (römisch-katholische Pfarrkirche von Oberlaa, die sich am Oberlaaer Platz im 10. Wiener Gemeindebezirk ([[Favoriten]]) befindet. Die Pfarre gehört zum Stadtdekanat 10 der Erzdiözese Wien"}, {"kategorie": "", "text": "Eine Kirche wird in Oberlaa schon 1267 bezeugt. Etwa seit 1324 war sie Pfarrkirche. Während der Zweiten Türkenbelagerung Wiens 1683 zerstört, fand zunächst nur ein notdürftiger Wiederaufbau statt. Erst in den Jahren 1744–1746 errichtete Mathias Gerl den heutigen Kirchenbau im Barockstil"}, {"kategorie": "", "text": "Die auffälligste Seite der Kirche ist die Südfassade, die durch das große Tor und einen Glockenturm mit Zwiebelhelm geprägt ist. Auf der mit Pilastern und Voluten verzierten Fassade stehen in Nischen die Statuen der Apostel Petrus und Paulus, geschaffen von Philipp Anton Höller zwischen 1744 und 1745. An der Nordseite, bei der Apsis, befindet sich außen das klassizistische Grabmal von Joseph Ritter von Vallemary"}, {"kategorie": "", "text": "Die Innenausstattung der Kirche umfasst den Hauptaltar von Sebastian Haupt (um 1759) mit einem Hochaltarbild des heiligen Ägidius von Johann Ignaz Cimbal. Die reich verzierte Kanzel stammt von Johann Tabotta (um 1760) und zeigt den heiligen Johannes den Evangelisten. Weitere Kunstwerke sind Figuren des heiligen Florian, des heiligen Donatus, eine Madonnenfigur, ein Altärchen und Figuren des heiligen Josef mit Kind und des heiligen Antonius von Padua"}, {"kategorie": "", "text": "Die Kirchenbänke und die Kommunionbank aus Marmor sind barock. In der Sakristei gibt es einen Schrank und ein Kruzifix aus dem 18. Jahrhundert, sowie ein Taufbecken aus rotem Marmor von Joseph Allbrecht (1777)"}, {"kategorie": "", "text": "Die Orgel, gebaut 1903 von Matthäus Mauracher, hat 15 Register, zwei Manuale und ein Pedal, und zeigt sich in Neorenaissanceformen."}]'::jsonb, ''),
  ('i-kunntad-mi-in-gaunzn-toog-nua-von-indianakropfn-eanaean-des-luftige-biskwit-mit-da-vanillikreem-is-aafoch-a-traum', 'I kunntad mi in gaunzn Toog nua von Indianakropfn eanäan - des luftige Biskwit mit da Vanillikreem is aafoch a Traum!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich könnte mich den ganzen Tag nur von Indianerkrapfen ernähren – das luftige Biskuit mit der Vanillecreme ist einfach ein Traum!', '[{"kategorie": "wörtlich", "text": "\"Indianerkrapfen allein würden mir als Tagesnahrung völlig reichen – diese zwei ausgehöhlten Biskuit-Halbkugeln mit vanilliertem Schlagobers sind einfach ein Gedicht!\"  2. Gebt mir nur Indianerkrapfen und ich bin versorgt – so fluffig, so cremig, so geil!  3. Solang’s Indianerkrapfen gibt, brauch ich weder Mittagessen noch Abendessen – die Dinger machen mich einfach glücklich!"}]'::jsonb, ''),
  ('indiana-mit-schloog', 'Indiana mit Schloog', 'der', '', '', 'Wiener Küche & Gaumenfreuden', 'Indianer mit Schlag', '[{"kategorie": "wörtlich", "text": "\"Mehlspeise zu Ehren der Indianer\" (von einem Wiener Zuckerbäcker 1820 kreierte Mehlspeise zu Ehren zweier damals in Wien gastierender indischer Artisten [\"die berühmten Indianer\" Thomas Bauleau und Kurom Balahia Titecan])"}, {"kategorie": "Kulinarik", "text": "Süßspeise aus zwei ausgehöhlten Biskuit-Halbkugeln, die mit gezuckertem, vanilliertem Schlagobers (Creme Chantilly) zusammengesetzt, aprikotiert und mit Schokolade überzogen werden"}, {"kategorie": "", "text": "[[Indianerkrapfen]], (Deutschland): \"Mohrenkopf\", \"Schokokuss\""}]'::jsonb, ''),
  ('nuara-echta-wiena-waass-dass-a-gscheida-indiana-mit-schloog-de-woeoed-bessa-mochd', 'Nuara echta Wiena waass, dass a gscheida Indiana mit Schloog de Wööd bessa mochd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Nur ein echter Wiener weiß, dass ein g’scheiter Indianer mit Schlag die Welt besser macht!', '[{"kategorie": "wörtlich", "text": "\"Nur ein echter Wiener weiß, dass ein g’scheiter Indianer mit Schlag, diese herrliche Mehlspeise aus zwei ausgehöhlten Biskuit-Halbkugeln mit vanilliertem Schlagobers,  die Welt wirklich besser macht!\"  2. Wer Wien kennt, weiß: Ohne Indianer mit Schlag fehlt was im Leben!  3. Ein echter Wiener braucht keinen Champagner – ein Indianer mit Schlag reicht völlig fürs Glück!"}]'::jsonb, 'Indiana mit Schloog'),
  ('mei-schaeaef-is-soo-a-idipfaereida-dea-daedad-sogoa-in-da-biibl-nooch-tippfoeoela-suachn', 'Mei Schääf is soo a Idipfäreida - dea dädad sogoa in da Biibl nooch Tippfööla suachn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mein Chef ist so ein I-Tüfel-Reiter - der täte sogar in der Bibel nach Tippfehler suchen!', '[{"kategorie": "wörtlich", "text": "\"Mein Chef ist so ein I-Tüpfel-Reiter – der findet selbst in der Heiligen Schrift noch einen Tippfehler!\"  2. Mein Chef ist so ein Pedant – der würd sogar dem lieben Gott jeden Tippfehler rot anstreichen!  3. Mein Chef ist ein [[Erbsenzähler]], wie er im Buche steht - der kontrolliert sogar die Fußnoten vom Papst, und findet garantiert was!"}]'::jsonb, ''),
  ('so-a-idipfaelreida-dea-wiad-neavoeoes-waunna-beischdrich-woogld', 'So a Idipfälreida - dea wiad neavöös, waunna Beischdrich woogld!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'So ein I-Tüpfelchen-Reiter – der wird nervös, wenn ein Beistrich wackelt!', '[{"kategorie": "wörtlich", "text": "\"So ein I-Tüpfel-Reiter – der kriegt Schnappatmung, wenn ein Komma schief steht!\"  2. So ein Erbesenzähler – der wird panisch, wenn ein Apostroph nicht richtig sitzt!  3. Der Typ ist ein richtiger [[Pitzler]] - kaum ist ein Satzzeichen nicht auf Linie, dreht er durch!"}]'::jsonb, ''),
  ('mit-dem-kaunnst-ned-auf-ualaub-foan-dea-eabsnzoeoela-reegd-si-scho-auf-waunnst-auf-da-pizza-a-olivn-mea-host-ois-ea', 'Mit dem kaunnst ned auf Ualaub foan - dea Eabsnzööla reegd si scho auf, waunnst auf da Pizza a Olivn mea host ois ea!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mit dem kannst nicht auf Urlaub fahren - dieser Erbsenzähler regt sich schon auf, wenn du auf der Pizza eine Olive mehr hast als er!', '[{"kategorie": "wörtlich", "text": "\"Mit dem kannst du nicht auf Urlaub fahren – der Erbsenzähler dreht schon durch, wenn auf deiner Pizza eine Olive mehr liegt als auf seiner!\"  2. Mit so einem pingeligen Erbsenzähler macht Urlaub keinen Spaß – der schielt dauernd auf deinen Teller und regt sich auf, wenn du auf der Pizza eine Olive mehr hast als er!  3. So ein Erbsenzähler! Schon eine Olive zu viel auf deiner Pizza bringt ihn an den Rand des Nervenzusammenbruchs!"}]'::jsonb, ''),
  ('maunche-haum-in-sinn-fias-groosse-aundare-bleim-a-leebm-laung-deppade-lausklauwa', 'Maunche haum in Sinn fias Groosse - aundare bleim a Leebm laung deppade Lausklauwa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Manche haben den Sinn fürs Große - andere bleiben ein Leben lang nur depperte Lausklauber!', '[{"kategorie": "wörtlich", "text": "\"Manche sehen das große Ganze – Lausklauber dagegen hängen ihr ganzes Leben am Arschhaar der Genauigkeit!\"  2. Visionäre schreiben Geschichte – Erbsenzähler streiten über Tippfehler!  3. Visionäre Freigeister heben ab, während blöde Pedanten noch ihre Büroklammern nach Farbe sortieren!"}]'::jsonb, ''),
  ('so-iwamiadich-wia-dea-si-giibd-kunntad-ma-maanan-dea-hod-de-woeoed-allaanich-eafundn', 'So iwamiadich, wia dea si giibd, kunntad ma maanan, dea hod de Wööd allaanich eafundn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'So übermütig, wie er sich gibt, könnte man meinen, er hätte die Welt persönlich erfunden!', '[{"kategorie": "wörtlich", "text": "\"So übermütig, wie er sich gibt, könnte man meinen, er hätte das Universum allein erschaffen!\"  2. So wichtig, wie der sich nimmt, müsste man meinen, die Erde dreht sich nur wegen ihm!  3. Er stolziert herum, als hätte er persönlich das Sonnenlicht patentiert - der traut sich eindeutig zu viel zu!"}]'::jsonb, ''),
  ('kaum-hoda-drei-bia-intus-wiada-iwamiadich-und-glaubd-ea-is-da-kaisa-von-simmaring', 'Kaum hoda drei Bia intus, wiada iwamiadich und glaubd, ea is da Kaisa von Simmaring!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Kaum hat er drei Bier intus, wird er übermütig und glaubt, er sei der Kaiser von Simmering!', '[{"kategorie": "wörtlich", "text": "\"Drei Bier, und schon wird er übermütig und hält sich für den Kaiser von Simmering!\"  2. Ein paar Bier reichen, und er marschiert voller Elan auf wie der Großfürst von Simmering!  3. Drei Bier, und schon wird er überschwänglich und glaubt, er ist Franz Joseph mit Goldkette und Simmeringer Bezirksausweis!"}]'::jsonb, ''),
  ('si-ins-gwaund-schmeissn', 'si ins Gwaund schmeissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich ins Gewand schmeißen', '[{"kategorie": "wörtlich", "text": "\"sich ins Gewand werfen\""}, {"kategorie": "scherzhaft für", "text": "sich anziehen, sich ankleiden, sich zurechtmachen, [[in d''Hüüsn foan]]"}]'::jsonb, 'Schmeiss di ins Gwaund, da Besuuch is glei doo!'),
  ('schmeiss-di-ins-gwaund-da-besuuch-is-glei-doo', 'Schmeiss di ins Gwaund, da Besuuch is glei doo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schmeiß dich ins Gewand, der Besuch ist gleich da!', '[{"kategorie": "wörtlich", "text": "\"Zieh dich an, der Besuch ist gleich da!\"  2. Mach dich fertig, der Besuch steht gleich vor der Tür!  3. Zack zack, rein ins G’wand, der Besuch ist schon im Anmarsch!"}]'::jsonb, 'si ins Gwaund schmeissn'),
  ('si-ins-gwaund-haun', 'si ins Gwaund haun', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich ins Gewand hauen', '[{"kategorie": "wörtlich", "text": "\"sich ins Gewand werfen\""}, {"kategorie": "scherzhaft für", "text": "sich anziehen, sich ankleiden, sich zurechtmachen, [[in d''Hüüsn foan]]"}]'::jsonb, 'I hau mi schnöö ins Gwaund, daunn kemma schdaadn!'),
  ('i-hau-mi-schnoeoe-ins-gwaund-daunn-kemma-schdaadn', 'I hau mi schnöö ins Gwaund, daunn kemma schdaadn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hau mich schnell ins Gewand, dann können wir starten!', '[{"kategorie": "wörtlich", "text": "\"Ich werf mich schnell ins Gewand, dann können wir los!\"  2. Ich zieh mich nur schnell an, dann geht’s los!  3. Ich spring nur schnell in die Klamotten, dann bin ich soweit!"}]'::jsonb, ''),
  ('si-in-taloon-haun', 'si in Taloon haun', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich in den Talon hauen', '[{"kategorie": "wörtlich", "text": "\"sich die Trümpfe aus dem Talon holen\""}, {"kategorie": "allg.", "text": "\"sich in Schale werfen\", \"sich aufputzen\", sich schönmachen, sich herausputzen, sein schönstes Gewand anziehen"}, {"kategorie": "scherzhaft für", "text": "\"in den Talon abtauchen\", verschwinden, das Weite suchen"}, {"kategorie": "", "text": "\"sich aufs Ohr hauen\", sich schlafen legen, \"sich unter die Decke verziehen\""}]'::jsonb, 'Wien is a Schdodt, de haud si fiad Gääst so richtig in Taloon!'),
  ('wien-is-a-schdodt-de-haud-si-fiad-gaeaest-so-richtig-in-taloon', 'Wien is a Schdodt, de haud si fiad Gääst so richtig in Taloon!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wien ist eine Stadt, die haut sich für ihre Gäste so richtig in den Talon!', '[{"kategorie": "wörtlich", "text": "\"Wien ist eine Stadt, die sich für ihre Touristen so richtig in Schale wirft!\"  2. Wien zeigt sich seinen Gästen stets von seiner allerschönsten Seite!  3. Wien holt alle Trümpfe aus dem Talon, um sich für seine Gäste so richtig in Szene zu setzen!"}]'::jsonb, ''),
  ('hau-di-in-taloon', 'Hau di in Taloon!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Haue dich in den Talon!', '[{"kategorie": "wörtlich", "text": "\"Tauch ab in den Talon!\"  2. (scherzhaft für): Verschwinde!  3. Hau ab!  4. [[Vaputz]] di!  5. [[Hau]] di in Rettich!  6. [[Vazupf]] di!  7. [[Draa]] di!  8. [[Gee]] päule!  8. [[Hau]] di iwad Heisa!"}]'::jsonb, ''),
  ('i-hau-mi-jetzd-in-taloon-waeu-des-muang-wiad-a-hoata-toog', 'I hau mi jetzd in Taloon - wäu des muang wiad a hoata Toog!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich hau mich jetzt in den Talon - denn das morgen wird ein harter Tag!', '[{"kategorie": "wörtlich", "text": "\"Ich hau mich jetzt aufs Ohr, denn morgen wartet ein harter Tag auf mich!\"  2. Ich leg mich jetzt schlafen - denn der Tag morgen wird anstrengend genug!\"  3. Ich verzieh mich jetzt unter die Decke, denn der Tag morgen wird ein Wahnsinn!"}]'::jsonb, 'si in Taloon haun'),
  ('wos-im-taloon-haum', 'wos im Taloon haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'etwas im Talon haben', '[{"kategorie": "wörtlich", "text": "\"etwas in der Hinterhand haben\""}, {"kategorie": "", "text": "etwas in petto haben"}, {"kategorie": "", "text": "etwas in Reserve halten"}, {"kategorie": "", "text": "ein Ass im Ärmel haben"}]'::jsonb, 'Loss eam deppad reedn - I hob no wos im Taloon, dassa si auscheissn wiad!'),
  ('loss-eam-deppad-reedn-i-hob-no-wos-im-taloon-dassa-si-auscheissn-wiad', 'Loss eam deppad reedn - I hob no wos im Taloon, dassa si auscheissn wiad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Lass ihn deppert reden - ich hab noch was im Talon, dass er sich anscheißen wird!', '[{"kategorie": "wörtlich", "text": "\"Lass ihn ruhig blöd daherreden – ich hab noch was im Talon, da wird ihm das Lachen gleich im Hals steckenbleiben!\"  2. Lass ihn nur sudern – ich hab noch einen Stich im Ärmel, da wird er sich vor lauter Blamage gleich gepflegt anscheißen!  3. Der redet sich grad ins Aus – denn ich hab noch einen Trumpf im Talon, der ihn gleich aus dem letzten Loch pfeifen lassen wird!"}]'::jsonb, 'wos im Taloon haum'),
  ('des-is-nua-a-klaans-jaukal-des-meaksd-ned-amoi', 'Des is nua a klaans Jaukal, des meaksd ned amoi!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Das ist nur ein kleines Jaukerl, das merkst du nicht einmal!', '[{"kategorie": "wörtlich", "text": "\"Das ist nur ein kleines Piekserchen, das merkst du kaum!\"  2. Das ist nur ein kleiner Nadelstich – den spürst du kaum!  3. Das ist nur eine winzige Spritze, die zwickt nicht mal richtig!"}]'::jsonb, ''),
  ('es-gibt-ka-puival-und-ka-jaukal-gegen-d-boosheid', 'Es gibt ka Puival und ka Jaukal gegen d''Boosheid!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Es gibt kein Pulverchen und kein Jaukerl gegen die Bosheit!', '[{"kategorie": "wörtlich", "text": "\"Gegen Bosheit gibt es kein Wundermittel und auch keine Schutzimpfung!\"  2. Bosheit lässt sich weder wegspritzen noch wegimpfen!  3. Gegen Bosheit gibt''s weder Pille noch Spritze!"}]'::jsonb, ''),
  ('bei-ana-waundarung-hob-i-imma-a-jausn-im-rucksock', 'Bei ana Waundarung hob I imma a Jausn im Rucksock!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei einer Wanderung hab ich immer eine Jause im Rucksack!', '[{"kategorie": "wörtlich", "text": "\"Bei einer Wanderung hab ich immer eine Brotzeit im Rucksack!\"  2. Wenn ich wandern gehe, packe mir für unterwegs immer eine Verpflegung ein!  3. Auf Wandertouren hab ich immer eine kleine Stärkung dabei!"}]'::jsonb, ''),
  ('zua-teejausn-gibds-imma-an-frischn-obstfleck', 'Zua Teejausn gibds imma an frischn Obstfleck!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Zur Teejausen gibt es immer einen frischen Obstfleck!', '[{"kategorie": "wörtlich", "text": "\"Zum Nachmittagstee gibt es immer einen frischen Blechkuchen mit Obstbelag!\"  2. Zur Teepause am Nachmittag gibt es regelmäßig frischen Obstkuchen vom Blech!  3. Zum Nachmittagstee gibt’s immer einen saftigen Kuchen mit Obst vom Blech!"}]'::jsonb, ''),
  ('zua-kaffeejausn-gibds-imma-briooschkipfaln', 'Zua Kaffeejausn gibds imma Briooschkipfaln!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Zur Kaffeejause gibt es immer Briochekipferln!', '[{"kategorie": "wörtlich", "text": "\"Zum Nachmittagskaffee gibt''s immer Brioche-Hörnchen!\"  2. Zur Kaffeepause wird regelmäßig feines Brioche-Gebäck serviert!  3. Zum Kaffee am Nachmittag stehen immer frische Brioche-Hörnchen bereit!"}]'::jsonb, ''),
  ('rapid-hod-si-gestan-wiara-jausngegna-praesentiad', 'Rapid hod si gestan wiara Jausngegna präsentiad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Rapid hat sich gestern wie ein Jausengegner präsentiert!', '[{"kategorie": "wörtlich", "text": "\"Der Sportklub Rapid Wien hat sich gestern als Jausengegner präsentiert!\"  2. Rapid war gestern ein leicht zu besiegender Aufbaugegner!  3. Rapid war gestern für den Gegner nicht mehr als ein Punktelieferant!"}]'::jsonb, ''),
  ('so-an-eiagegna-hauma-scho-laung-nimma-zuaglost-kriagd', 'So an Eiagegna hauma scho laung nimma zuaglost kriagd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'So einen Eiergegner haben wir schon lange nicht mehr zugelost bekommen!', '[{"kategorie": "wörtlich", "text": "\"Einen derart leichten Gegner haben wir schon lange nicht mehr zugelost bekommen!\"  2. Die uns zugeloste Mannschaft hätten wir früher als Aufwärmgegner durchgewunken!  3. So eine dankbare Auslosung hatten wir schon lange nicht mehr!"}]'::jsonb, ''),
  ('jass1', 'Jass1', 'der', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Jass', '[{"kategorie": "wörtlich", "text": "\"Jass\" (vom niederländischen \"jas\"=\"Mantel\")"}, {"kategorie": "allg.", "text": "Überrock, taillierter Kurzmantel, \"Blazer\""}]'::jsonb, 'Sei eleganta Jass valeid eam an Hauch von britischn Schick!'),
  ('jass2', 'Jass2', '', '', '', 'Grundwortschatz Wienerisch', 'Jass, der/das', '[{"kategorie": "wörtlich", "text": "\"Jass\" (vom französischen \"as\"=\"Ass\")"}, {"kategorie": "Kartenspielerjargon", "text": "\"Trumpf\", \"Ass\", \"höchste Spielkarte\""}, {"kategorie": "fig.", "text": "\"anerkannte Autorität\", Fachmann, Meister, Könner, Großmeister, Koryphäe, Genie, [[Kapazunder]]"}]'::jsonb, 'Da Jass is de heechsde Schbüükoatn im Zensan!'),
  ('da-jass-is-de-heechsde-schbueuekoatn-im-zensan', 'Da Jass is de heechsde Schbüükoatn im Zensan!', '', '', '', 'Wiener Kartentipplerjargon', 'Der Jass ist die höchste Spielkarte im Zensern!', '[{"kategorie": "wörtlich", "text": "\"Das Jass stellt im [[Zensern]] die höchste Spielkarte dar!\"  2. \"Das Jass steht im Zensern über allen anderen Karten!\"  3. \"Der Jass ist im Zensern der absolute Trumpf!\""}]'::jsonb, ''),
  ('in-da-quantnfysik-isara-jass', 'In da Quantnfysik isara Jass!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'In der Quantenphysik ist er ein Jass!', '[{"kategorie": "wörtlich", "text": "\"Er ist eine anerkannte Autorität in der Quantenphysik!\"  2. Auf dem Gebiet der Quantenphysik ist er eine wahre Koryphäe!  3. Er ist wahrlich ein Kapazunder der Quantenphysik!"}]'::jsonb, ''),
  ('sei-eleganta-jass-valeid-eam-an-hauch-von-britischn-schick', 'Sei eleganta Jass valeid eam an Hauch von britischn Schick!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sein eleganter Jass verleiht ihm einen Hauch von britischem Chic!', '[{"kategorie": "wörtlich", "text": "\"Sein eleganter Überrock verleiht ihm einen Hauch von britischem Chic!\""}, {"kategorie": "", "text": "Sein stilvoller Überrock strahlt britische Noblesse aus!  3. Mit dem taillierten Kurzmantel sieht er aus, als wär er gerade aus London eingeflogen!"}]'::jsonb, ''),
  ('wos-fiara-jassischa-schachzug-des-woa-taktik-auf-heechstn-nivoo', 'Wos fiara jassischa Schachzug - des woa Taktik auf heechstn Nivoo!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Was für ein jassischer Schachzug – das war Taktik auf höchstem Niveau!', '[{"kategorie": "wörtlich", "text": "\"Was für ein genialer Schachzug – das war Taktik auf höchstem Niveau!\"  2. Was für ein meisterhaft durchdachter Schachzug – strategisch nahezu perfekt umgesetzt!  3. Eine taktisches Meisterleistung – präzise, klug und perfekt durchdacht!"}]'::jsonb, ''),
  ('des-is-kaa-jass-des-isa-owajass-dea-siechds-loch-no-bevuas-doo-is', 'Des is kaa Jass, des isa Owajass - dea siechds Loch, no bevuas doo is!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Das ist kein Jass, das ist ein Oberjass - der sieht''s Loch, noch bevor''s da ist!', '[{"kategorie": "wörtlich", "text": "\"Das ist kein Könner, das ist ein Überkönner - der sieht die Lücke, noch bevor sie entsteht!\"  2. Der ist kein Könner, der ist ein Maestro – der liest das Spiel wie ein offenes Buch!  3. Der ist kein Spieler, der ist ein Überspieler - der sieht den freien Passweg, bevor der Gegner überhaupt weiß, wo er steht!"}]'::jsonb, ''),
  ('wia-san-aum-juchaeae-gschdaundn', 'Wia san aum Juchää gschdaundn!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Wir sind auf dem Juchhe gestanden!', '[{"kategorie": "wörtlich, Theaterjargon", "text": "(i) \"Wir sind auf der obersten Galerie gestanden!\"  (ii) \"Wir standen ganz oben auf dem höchsten Rang!\""}, {"kategorie": "allg.", "text": "(i) \"Wir sind ganz oben auf dem Gipfel gestanden!\"  (ii) \"Wir standen ganz oben, am höchsten Punkt des Berges!\""}]'::jsonb, ''),
  ('ooman-aufn-juchaeae-do-host-a-gsichd-wiara-kaisa-de-woeoed-is-auf-amoi-gaunz-klaa-und-da-oitoog-so-weit-weg', 'Ooman aufn Juchää, do host a Gsichd wiara Kaisa - de Wööd is auf amoi gaunz klaa und da Oitoog so weit weg!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Oben auf dem Juchhe hast du ein Gesicht wie ein Kaiser - die Welt ist auf einmal ganz klein und der Alltag weit weg!', '[{"kategorie": "wörtlich", "text": "\"Oben auf dem Gipfel hast du ein Gesicht wie ein Kaiser - die Welt ist auf einmal ganz klein und der Alltag so weit weg!\"  2. Am Gipfel fühlst du dich wie ein König über den Wolken – alles andere schrumpft unter dir zusammen und scheint auf einmal so weit weg!  3. Dort oben auf der Bergspitze thronst du wie ein Herrscher – die Sorgen bleiben im Tal zurück und sind auf einmal ganz weit weg!"}]'::jsonb, ''),
  ('da-applaus-ausn-juchaeae-woar-aum-lautastn-duat-oom-schdengan-de-leit-de-in-schlechtastn-blick-haum-owa-oft-de-schdaeakste-meinung', 'Da Applaus ausn Juchää woar aum lautastn - duat oom schdengan de Leit, de in schlechtastn Blick haum, owa oft de schdäakste Meinung!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Der Applaus vom Juchhe war am lautesten - dort oben stehen die Leute, die den schlechtesten Blick haben, aber die stärkste Meinung!', '[{"kategorie": "wörtlich", "text": "\"Vom obersten Rang kam der kräftigste Beifall – von jenen mit der schlechtesten Sicht, aber der stärksten Stimme!\"  2. Die größten Emotionen kamen vom billigsten Stehplatzrang – ganz oben, ganz weit weg und trotzdem ganz nah am Geschehen!  3. Die heftigste Reaktion kam vom Juchhe – dort, wo man nicht viel sieht, aber umso intensiver mitfühlt!"}]'::jsonb, ''),
  ('ooman-is-oom-und-untn-is-unt-und-dazwischn-schbueued-si-s-leebm-oo', 'Ooman is oom und untn is unt - und dazwischn schbüüd si s''Leebm oo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Oben ist oben und unten ist unten - und dazwischen spielt sich das Leben ab!', '[{"kategorie": "wörtlich", "text": "\"Oben bleibt oben, unten bleibt unten – doch das Leben tobt dazwischen!\"  2. Zwischen Höhenflug und Tiefflug liegt der Alltag unseres Lebens!  3. Oben und unten sind nur Extreme – das wirkliche Leben liegt dazwischen!"}]'::jsonb, ''),
  ('ea-is-wiida-im-aansa-aufgwochd-und-des-ned-zum-easchdn-moi', 'Ea is wiida im Aansa aufgwochd - und des ned zum easchdn Moi!', '', '', '', 'Wiener Gaunersprache', 'Er ist wieder im Einser aufgewacht - und das nicht zum ersten Mal!', '[{"kategorie": "wörtlich", "text": "\"Er ist wieder im Wiener Landesgericht aufgewacht - und das nicht zum ersten Mal!\"  2. Er sitzt wieder im Wiener Landesgericht – kein unbekanntes Terrain für ihn!  3. Er wurde wieder ins Wiener Straflandesgericht eingeliefert - sicher nichts Neues für ihn!"}]'::jsonb, ''),
  ('ea-hod-lauta-aansa-im-zeignis', 'Ea hod lauta Aansa im Zeignis!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat lauter Einser im Zeugnis!', '[{"kategorie": "wörtlich", "text": "\"Er hat nur Einser im Zeugnis!\"  2. Er hat ein Zeugnis wie gemalt - lauter Einser!  3. Er hat in jedem Zeugnisfach die Bestnote!"}]'::jsonb, ''),
  ('waunnsd-gwiinna-wueuesd-brauchsd-kaan-zwaara-do-brauchsd-an-aansa-wia-eam', 'Waunnsd gwiinna wüüsd, brauchsd kaan Zwaara - do brauchsd an Aansa wia eam!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Wenn du gewinnen willst, brauchst du keinen Zweier – da brauchst du einen Einser wie ihn!', '[{"kategorie": "wörtlich, allg.", "text": "\"Wer Erfolg haben will, braucht keinen Zweier - der braucht einen Einser wie ihn!\"  2. (Fußballerjargon): Wer aufs Siegertreppchen will, braucht einen wie ihn – einen Spieler der Extraklasse!  3. Wenn du vorne mitspielen willst, brauchst du jemanden mit seiner Klasse - eine echte Nummer eins!"}]'::jsonb, ''),
  ('da-schwoaze-oidteima-mit-de-vachromtn-foeoeng-is-a-echta-aansa-top-zuaschdaund-baujoa-51-fost-wiar-ausn-schauraum', 'Da schwoaze Oidteima mit de vachromtn Fööng is a echta Aansa -top Zuaschdaund, Baujoa ''51, fost wiar ausn Schauraum!', '', '', '', 'Wiener Mechaniker-Slang', 'Der schwarze Oldtimer mit den verchromten Felgen ist ein echter Einser – top Zustand, Baujahr ’51, fast wie aus dem Schauraum!', '[{"kategorie": "wörtlich", "text": "\"Der schwarze Oldtimer ist ein Einser vom Feinsten – schwarzer Lack, glänzende Felgen, und läuft wie ein Kätzchen!\"  2. Ein top gepflegter Klassiker: schwarzer Oldtimer, Baujahr ''51, originalgetreue Felgen – ein echter Einser unter den Veteranen!  3. Ein echter Einser auf vier Rädern – mit den massiven Chromfelgen und dem tiefen Brummen ist dieser Oltimer, Baujahr ''51, einfach das Nonplusultra!"}]'::jsonb, ''),
  ('an-reemischn-aansa-kriang', 'an reemischn Aansa kriang', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen römischen Einser bekommen', '[{"kategorie": "wörtlich", "text": "\"einen Einser mit Sternchen bekommen\" (d.h. eine noch bessere Beurteilung als die beste Schulnote erhalten)"}, {"kategorie": "", "text": "\"eine goldene Eins abstauben\""}, {"kategorie": "", "text": "\"einen Einser mit Mascherl bekommen\""}]'::jsonb, 'Da Aufsotz woa brilljant - si hod vom Leara an reemischn Aansa kriagd!'),
  ('da-aufsotz-woa-brilljant-si-hod-vom-leara-an-reemischn-aansa-kriagd', 'Da Aufsotz woa brilljant - si hod vom Leara an reemischn Aansa kriagd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Aufsatz war brillant - sie hat vom Lehrer einen römischen Einser gekriegt!', '[{"kategorie": "wörtlich", "text": "\"Der Aufsatz war brillant - sie hat vom Lehrer einen römischen Einser dafür bekommen!\"  2. Der Aufsatz war so brillant, der Lehrer hat ihr dafür einen römischen Einser gegeben!  3. Als er ihren Aufsatz gelesen hatte, meinte der Lehrer nur: „Römischer Einser – mit Lorbeerkranz!“"}]'::jsonb, ''),
  ('bei-wem-an-dickn-aansa-haum', 'bei wem an dickn Aansa haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'bei jemandem einen dicken Einser haben', '[{"kategorie": "wörtlich", "text": "\"bei jemandem einen dicken Pluspunkt haben\""}, {"kategorie": "fig.", "text": "bei jemandem einen dicken Stein im Brett haben"}, {"kategorie": "", "text": "in jemandes Gunst ganz oben stehen"}]'::jsonb, 'Dea hod ma beim Umzuug ghoifn - jetzt hoda aan dickn Aansa bei mia!'),
  ('dea-hod-ma-beim-umzuug-ghoifn-jetzt-hoda-aan-dickn-aansa-bei-mia', 'Dea hod ma beim Umzuug ghoifn - jetzt hoda aan dickn Aansa bei mia!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der hat mir beim Umzug geholfen - jetzt hat er einen dicken Einser bei mir!', '[{"kategorie": "wörtlich", "text": "\"Der hat mir beim Umzug geholfen - jetzt hat er einen dicken Pluspunkt bei mir!\"  2. Der hat mir den Arsch gerettet beim Umzug – jetzt steht er in meiner Gunst ganz weit oben!  3. Ohne seine Hilfe wäre der Umzug gescheitert - er hat jetzt einen dicken Stein bei mir im Brett!"}]'::jsonb, 'bei wem an dickn Aansa haum'),
  ('davoojaukn-kaunnsd-wem-aundan-i-bleib-bis-i-mei-goeoed-kriag', 'Davoojaukn kaunnsd wem aundan - I bleib, bis I mei Gööd kriag!', '', '', '', 'Wiener Gaunersprache', 'Davonjagen kannst du wen anderen - ich bleibe, bis ich mein Geld krieg!', '[{"kategorie": "wörtlich", "text": "\"Fortjagen lass ich mich von dir sicher nicht – ich bleibe hier, bis ich bezahlt werde!\"  2. Davonscheuchen kannst wen anderen – ich bleib hier sitzen, bis die Scheine am Tisch liegen!  3. In die Flucht schlagen kannst du andere – ich geh erst, wenn ich mein Geld hab!"}]'::jsonb, ''),
  ('wia-d-haeae-kumman-is-sans-auf-an-gschdoolanan-mopal-davoogjaukd', 'Wia d''Hää kumman is, sans auf an gschdoolanan Mopal davoogjaukd!', '', '', '', 'Wiener Gaunersprache', 'Wie die Höh gekommen ist, sind sie auf einem gestohlenen Moperl davongejaukt!', '[{"kategorie": "wörtlich", "text": "\"Als die Polizei kam, sind sie auf einem gestohlenen Moped davongejagt!\"  2. Kaum war die Polizei da, sind sie mit dem geklauten Moped davongedüst!  3. Als die Sirenen heulten, rasten sie auf dem gestohlenen Moped wie der Teufel davon!"}]'::jsonb, ''),
  ('dea-lossd-si-ned-so-leichd-vajaukn-dea-bleibd-bisa-kriagd-woosa-wueue', 'Dea lossd si ned so leichd vajaukn - dea bleibd, bisa kriagd, woosa wüü!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der lässt sich nicht so leicht verjauken - der bleibt, bis er kriegt, was er will!', '[{"kategorie": "wörtlich", "text": "\"Der lässt sich nicht so schnell vertreiben - der wartet, bis er bekommt, was er will!\"  2. Den wirst so schnell nicht los – der sitzt das aus, bis er kriegt, was er will!  3. Den kannst hundert Mal rauskomplimentieren – der kommt immer wieder, bis er sein Ziel erreicht!"}]'::jsonb, ''),
  ('wem-mit-wos-jaukn-kenna', 'wem mit wos jaukn kenna', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden mit etwas jauken können', '[{"kategorie": "wörtlich", "text": "\"jemanden mit etwas jagen können\""}, {"kategorie": "", "text": "\"jemandem mit etwas gar nicht zu kommen brauchen\""}, {"kategorie": "", "text": "\"jemanden mit etwas um den Block jagen können\""}]'::jsonb, 'Mit an Brokkoli kaunnst mi jaukn!'),
  ('mit-an-brokkoli-kaunnst-mi-jaukn', 'Mit an Brokkoli kaunnst mi jaukn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Mit einem Brokkoli kannst du mich jauken!', '[{"kategorie": "wörtlich", "text": "\"Mit einem Brokkoli kannst du mich jagen!\"  2. Mit einem Brokkoli brauchst du mir gar nicht zu kommen!  3. Mit einem Brokkoli kannst du mich einmal um den Block jagen!"}]'::jsonb, 'wem mit wos jaukn kenna'),
  ('des-jaukd-ma-a-aungst-ei', 'Des jaukd ma a Aungst ei!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das jaukt mir eine Angst ein!', '[{"kategorie": "wörtlich", "text": "\"Das jagt mir Angst ein!\"  2. Das macht mir Angst!  3. Das bringt mich zum Fürchten!  4. Das lässt mir das Blut in den Adern gefrieren!"}]'::jsonb, ''),
  ('wia-weana-soong-jaenna-und-ned-januar-sunst-kunntad-ma-jo-glei-noch-piifkenaeaesiaen-auswaundan', 'Wia Weana soong Jänna und ned Januar - sunst kunntad ma jo glei noch Piifkenääsiän auswaundan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wir Wiener sagen ''Jänner'' und nicht ''Januar'' - sonst könnten wir ja gleich nach Piefkenäsien auswandern!', '[{"kategorie": "wörtlich", "text": "\"Wir Wiener sagen ''Jänner'' und nicht ''Januar'' - sonst könnten wir ja gleich nach Deutschland auswandern!\"  2. Wir Wiener sagen ''Jänner'' und nicht ''Januar'' - denn wir reden nicht nach deutschem Duden, sondern nach Gefühl!  3. ‚Jänner‘ sagt der Wiener – alles andere klingt für uns wie aus’m deutschen Wetterbericht!"}]'::jsonb, ''),
  ('tarock-oone-bia-is-wia-puudan-mit-sockn-meeglich-owa-iagendwia-fian-oasch', 'Tarock oone Bia is wia Puudan mit Sockn - meeglich, owa iagendwia fian Oasch!', '', '', '', 'Wiener Kartentipplerjargon', 'Tarock ohne Bier ist wie Pudern mit Socken – möglich, aber irgendwie für''n Arsch!', '[{"kategorie": "wörtlich", "text": "\"Tarock ohne Bier ist wie Sex mit Socken – möglich, aber irgendwie sinnlos!\"  2. \"Tarock zu spielen ohne Bier ist wie Sex zu haben mit Socken - theoretisch möglich, aber irgendwie falsch!  3. Tarock ohne Bier ist wie Heiraten ohne Schwiegermutter – theoretisch möglich, aber irgendwie für Arsch und Friedrich!"}]'::jsonb, ''),
  ('host-no-a-tarock-oda-ned', 'Host no a Tarock oda ned?', '', '', '', 'Wiener Kartentipplerjargon', 'Hast du noch eine Tarock oder nicht?', '[{"kategorie": "wörtlich", "text": "\"Ist das deine letzte Tarockkarte gewesen oder hast du noch eine zum Stechen?\"  2. Ist''s aus mit’m Tarockzauber oder kommt jetzt gar der [[Gschdiiss]] ums Eck?  3. So, mein Junge – jetzt musst du Farbe bekennen: Hast du noch eine Tarock oder nicht?"}]'::jsonb, ''),
  ('wea-tarockiad-brauchd-geduid-schmaeae-und-a-guade-haund', 'Wea tarockiad, brauchd Geduid, Schmää und a guade Haund!', '', '', '', 'Wiener Kartentipplerjargon', 'Wer tarockiert, braucht Geduld, Schmäh und eine gute Hand!', '[{"kategorie": "wörtlich", "text": "\"Tarock spielen erfordert Geduld, Taktik und ein gutes Blatt!\"  2. Wer Tarock spielt, muss strategisch denken und mit Ruhe agieren  – und ein wenig Glück gehört auch dazu!  3. Beim Tarockieren zählt Cleverness, Geduld und ein gutes Blatt zur rechten Zeit!"}]'::jsonb, ''),
  ('a-echta-tarockiira-waass-zeaschd-wiad-gschdochn-dann-easchd-gschbrochn', 'A echta Tarockiira waass - zeaschd wiad gschdochn, dann easchd gschbrochn!', '', '', '', 'Wiener Kartentipplerjargon', 'Ein echter Tarockierer weiß - zuerst wird gestochen, dann erst gesprochen!', '[{"kategorie": "wörtlich, Kartenspielerspruch", "text": "\"Ein guter Tarockspieler lässt erst die Karten sprechen – und dann sich selbst!\"  2. Einen gestandenen Tarockierer erkennst du daran, dass er vor’m Stich nicht viel redet – aber nachher dafür umso mehr!  3. Erst der Stich, dann die große Goschn – so machen''s die Profis unter den Tarockierern!"}]'::jsonb, ''),
  ('ee-kloa-echte-kartla-wissn-zeaschd-wiad-gschdochn-dann-easchd-gschbrochn', 'Ee kloa, echte Kartla wissn - zeaschd wiad gschdochn, dann easchd gschbrochn!', '', '', '', 'Wiener Kartentipplerjargon', 'Eh klar, echte Kartler wissen - zuerst wird gestochen, dann erst gesprochen!', '[{"kategorie": "wörtlich, Kartenspielerspruch", "text": "\"Ein guter Kartenspieler lässt erst die Karten sprechen – und dann sich selbst, eh klar!\"  2. Einen gestandenen Kartler erkennst du daran, dass er vor’m Stich nicht viel redet – aber nachher dafür umso mehr!  3. Erst der Stich, dann die große Goschn – so machen''s die Profis unter den Kartenspielern!"}]'::jsonb, ''),
  ('schbiiglein-schbiiglein-aun-da-waund-wea-is-da-beste-tarockand-im-laund', 'Schbiiglein, Schbiiglein aun da Waund - wea is da beste Tarockand im Laund?', '', '', '', 'Wiener Kartentipplerjargon', 'Spieglein, Spieglein an der Wand - wer ist der beste Tarockant im Land?', '[{"kategorie": "wörtlich, Kartenspielerspruch", "text": "\"Spieglein, Spieglein an der Wand - wer ist der beste Tarockspieler hier im Land?\"  2. Spieglein, Spieglein an der Wand - welcher Tarockant hat die ruhigste Hand?  3. Spieglein, Spieglein an der Wand: Ich bin der einzig echte Tarockant!"}]'::jsonb, ''),
  ('in-tarockaniaen-wiad-ned-gwoeoed-doo-wiad-gschdochn', 'In Tarockaniän wiad ned gwööd - doo wiad gschdochn!', '', '', '', 'Wiener Kartentipplerjargon', 'In Tarockanien wird nicht gewählt – da wird gestochen!', '[{"kategorie": "wörtlich", "text": "\"In Tarockanian wird nicht gewählt - sondern mit dem [[Gstieß]] gestochen!\"  2. In Tarockanien braucht''s keine Wahlen, denn es zählt immer nur der letzte Stich!  3. In Tarockanien brauchst du keinen Stimmzettel – nur den [[Pagat]] für''n letzten Stich!"}]'::jsonb, ''),
  ('dea-froogd-no-a-tarockpartii-dabei-woas-schoo-viire-in-da-frua', 'Dea froogd: ''No a Tarockpartii?'' - dabei woas schoo viire in da Frua!', '', '', '', 'Wiener Kartentipplerjargon', 'Der fragt: ''Noch eine Tarockpartie?'' - dabei war es schon vier Uhr früh!', '[{"kategorie": "wörtlich", "text": "\"Er fragt doch tatsächlich: ‚Noch eine Runde?‘ – dabei war''s schon vier Uhr früh!\"  2.  Kaum zu glauben, aber er wollte um vier Uhr morgens noch eine weitere Tarockrunde starten!  3. Vier Uhr früh, Augenringe bis zum Kinn – und er fragt ernsthaft: ‚Noch eine Runde Tarock?''"}]'::jsonb, ''),
  ('wia-san-a-eigschwaassde-tarockpartii-und-scheengn-uns-nix-wea-valiad-zoid-de-naeaechste-runde', 'Wia san a eigschwaassde Tarockpartii und scheengn uns nix - wea valiad, zoid de näächste Runde!', '', '', '', 'Wiener Kartentipplerjargon', 'Wir sind eine eingeschweißte Tarockpartie und schenken uns nix - wer verliert, zahlt die nächste Runde!', '[{"kategorie": "wörtlich", "text": "\"Wir sind ein eingeschworenes Tarock-Team, aber wir schenken uns nichts - der Verlierer blecht immer die nächste Runde!\"  2. Wir sind eine eingespielte Tarockrunde, bleiben einander aber nichts schuldig - bei uns wird scharf gespielt und fair gezahlt!  3. Wir vier sind eine beinharte Tarocktruppe – Gnade gibt’s bei uns keine, der Verlierer zahlt immer die nächste Runde!“"}]'::jsonb, ''),
  ('de-tarockiirarei-is-wiara-suchd-waunnsd-amoi-damit-aufaungsd-kaunnsd-nimma-aufhean', 'De Tarockiirarei is wiara Suchd - waunnsd amoi damit aufaungsd, kaunnsd nimma aufhean!', '', '', '', 'Wiener Kartentipplerjargon', 'Die Tarockierei ist wie ''ne Sucht - wenn du einmal anfängst, kannst du nicht mehr aufhören!', '[{"kategorie": "wörtlich", "text": "\"Tarockspielen macht süchtig – einmal angefangen, lässt es dich nicht mehr los!\"  2. Hat man einmal mit dem Tarockieren begonnen, endet man regelmäßig in schlaflosen Nächten!  3. Einmal Tarock, immer Tarock – wer zu spielen beginnt, für den gibt''s weder Ende noch Zurück!"}]'::jsonb, ''),
  ('mei-oida-hoid-de-schdundnlaunge-tarockiirarei-von-uns-viire-nimma-aus-s-naeaechste-moi-wiad-wiida-beim-wiatn-diiwaed', 'Mei Oida hoid de schdundnlaunge Tarockiirarei von uns viire nimma aus - s''näächste Moi wiad wiida beim Wiatn diiwäd!', '', '', '', 'Wiener Kartentipplerjargon', 'Meine Alte hält die stundenlange Tarockiererei von uns vieren nicht mehr aus - das nächste Mal wird wieder beim Wirten getippelt!', '[{"kategorie": "wörtlich", "text": "\"Meine Frau ist vom ständigen Tarockspielen in der Wohnung genervt – beim nächsten Mal müssen wir ins Wirtshaus ausweichen!\"  2. Zu Hause ist’s meiner Frau zu viel geworden mit unseren ewigen Tarockabenden – nächstes Mal geht’s ins Gasthaus!  3. Meine Alte daheim kann den stundenlangen Tarock-Stammtisch von uns vieren nicht mehr ertragen – ab jetzt werden die Karten wieder beim Wirten geklopft!"}]'::jsonb, ''),
  ('wea-kartld-brauchd-geduid-schmaeae-und-a-guade-haund', 'Wea kartld, brauchd Geduid, Schmää und a guade Haund!', '', '', '', 'Wiener Kartentipplerjargon', 'Wer kartelt, braucht Geduld, Schmäh und eine gute Hand!', '[{"kategorie": "wörtlich", "text": "\"Karten spielen erfordert Geduld, Taktik und ein gutes Blatt!\"  2. Wer Karten spielt, muss strategisch denken und mit Ruhe agieren  – und ein wenig Glück gehört auch dazu!  3. Beim Karteln zählt Cleverness, Geduld und ein gutes Blatt zur rechten Zeit!"}]'::jsonb, ''),
  ('de-kartlarei-is-wiara-suchd-waunnsd-amoi-damit-aufaungsd-kaunnsd-nimma-aufhean', 'De Kartlarei is wiara Suchd - waunnsd amoi damit aufaungsd, kaunnsd nimma aufhean!', '', '', '', 'Wiener Kartentipplerjargon', 'Die Kartlerei ist wie ''ne Sucht - wenn du einmal anfängst, kannst du nicht mehr aufhören!', '[{"kategorie": "wörtlich", "text": "\"Kartenspielen macht süchtig – einmal angefangen, lässt es dich nicht mehr los!\"  2. Hat man einmal mit dem Kartentippeln begonnen, endet man regelmäßig in schlaflosen Nächten!  3. Einmal Kartenspielen, immer immer Kartenspielen – wer zu spielen beginnt, für den gibt''s kein Ende und kein Zurück!"}]'::jsonb, ''),
  ('mei-oida-hoid-de-schdundnlaunge-kartlarei-von-uns-viire-nimma-aus-s-naeaechste-moi-wiad-wiida-beim-wiatn-diiwaed', 'Mei Oida hoid de schdundnlaunge Kartlarei von uns viire nimma aus - s''näächste Moi wiad wiida beim Wiatn diiwäd!', '', '', '', 'Wiener Kartentipplerjargon', 'Meine Alte hält die stundenlange Kartlerei von uns vieren nicht mehr aus - das nächste Mal wird wieder beim Wirten getippelt!', '[{"kategorie": "wörtlich", "text": "\"Meine Frau ist vom ständigen Kartenspielen bei uns in der Wohnung genervt – beim nächsten Mal müssen wir ins Wirtshaus ausweichen!\"  2. Zu Hause ist’s meiner Frau zu viel geworden mit unseren ewigen Kartenabenden – nächstes Mal geht’s ins Gasthaus!  3. Meine Alte daheim kann den stundenlangen Kartenstammtisch von uns vieren nicht mehr ertragen – ab jetzt werden die Karten wieder beim Wirten geklopft!"}]'::jsonb, ''),
  ('in-da-tarockei-wiad-ned-gwoeoed-doo-wiad-gschdochn', 'In da Tarockei wiad ned gwööd - doo wiad gschdochn!', '', '', '', 'Wiener Kartentipplerjargon', 'In der Tarockei wird nicht gewählt – da wird gestochen!', '[{"kategorie": "wörtlich", "text": "\"In der Tarockei wird nicht gewählt - sondern mit dem [[Gstieß]] gestochen!\"  2. In der Tarockei braucht''s keine Wahlen, denn es zählt immer nur der letzte Stich!  3. In der Tarockei brauchst du keinen Stimmzettel – nur den [[Pagat]] für''n letzten Stich!"}]'::jsonb, ''),
  ('in-tarockistan-wiad-ned-gwoeoed-doo-wiad-gschdochn', 'In Tarockistan wiad ned gwööd - doo wiad gschdochn!', '', '', '', 'Wiener Kartentipplerjargon', 'In Tarockistan wird nicht gewählt – da wird gestochen!', '[{"kategorie": "wörtlich", "text": "\"In Tarockistan wird nicht gewählt - sondern mit dem [[Gstieß]] gestochen!\"  2. In Tarockistan braucht''s keine Wahlen, denn es zählt immer nur der letzte Stich!  3. In Tarockistan brauchst du keinen Stimmzettel – nur den [[Pagat]] für''n letzten Stich!"}]'::jsonb, ''),
  ('so-gemma-schnopsn-koatn-hea-host-zeit-fiara-schnoeoes-bummal', 'So, gemma schnopsn, Koatn hea! Host Zeit fiara schnöös Bummal?', '', '', '', 'Wiener Kartentipplerjargon', 'So, gemma schnapsen, Karten her! Hast Zeit für ein schnelles Bummerl?', '[{"kategorie": "wörtlich", "text": "\"Na los, holen wir die Schnapskarten raus – Lust auf ein schnelles Spiel?\"  2. Zeit für ein [[Bummerl]]? Eine schnelle Runde Schnapsen geht sich noch aus, oder?  3. Karten raus, mein Freund – Lust auf eine schnelle Partie Schnapsen?"}]'::jsonb, ''),
  ('jetzt-samma-gschnopst', 'Jetzt samma gschnopst!', '', '', '', 'Wiener Gaunersprache', 'Jetzt sind wir geschnapst!', '[{"kategorie": "wörtlich", "text": "\"Jetzt sind wir geschnappt!\"  2. (fig.) \"Jetzt haben wir ausgespielt!\"  3. \"Das war''s!\"  4. \"Das Spiel ist vorbei!\""}]'::jsonb, ''),
  ('ois-oida-schnopsa-waassa-genau-woeoeche-koatn-schoo-draussn-san', 'Ois oida Schnopsa waassa genau, wööche Koatn schoo draussn san!', '', '', '', 'Wiener Kartentipplerjargon', 'Als alter Schnapser weiß er genau, welche Karten schon draußen sind!', '[{"kategorie": "wörtlich", "text": "\"Als erfahrener Schnapser weiß er ganz genau, welche Karten schon gefallen sind!\"  2. Als alter Schnapser merkt er sich jeden Stich - dem entgeht keine einzige Karte!  3. So lang wie der schon schnapst, hat er stets mehr Karten im Kopf als in der Hand!"}]'::jsonb, ''),
  ('kumm-hau-ma-uns-auf-an-schnopsa-und-schbueue-ma-a-schnoeoes-bummal-aus', 'Kumm, hau ma uns auf an Schnopsa und schbüü ma a schnöös Bummal aus!', '', '', '', 'Wiener Kartentipplerjargon', 'Komm, hauen wir uns auf einen Schnapser und spielen wir ein schnelles Bummerl aus!', '[{"kategorie": "wörtlich", "text": "\"Na komm, setzen wir uns auf eine Schnapspartie zusammen und klopfen wir ein schnelles Bummerl!\"  2. Komm, hock dich her auf eine Runde Schnapsen - ein schnelles Bummerl ist immer drin!  3. Lust auf einen Schnapser? Komm, spielen wir uns ein schnelles Bummerl aus!"}]'::jsonb, ''),
  ('wia-mit-so-an-schaasblaadl-aan-schnopsa-ausoong-kau-is-ma-a-raeaetsl', 'Wia mit so an Schaasblaadl aan Schnopsa ausoong kau, is ma a Räätsl!', '', '', '', 'Wiener Kartentipplerjargon', 'Wie man mit einem solchen Schasblattl einen Schnapser ansagen kann, ist mir ein Rätsel!', '[{"kategorie": "wörtlich", "text": "\"Wie man bei so einem schwachen Blatt einen Schnapser riskieren kann, ist mir schleierhaft!\"  2. Wer mit so einem mickrigen Blatt einen Schnapser ansagt, leidet an krasser Selbstüberschätzung!  3.Schnapser? Wie kann jemand glauben, dass er mit einem so mickrigen Blatt alle Stiche machen kann!"}]'::jsonb, ''),
  ('a-bummal-klopfn', 'a Bummal klopfn', '', '', '', 'Wiener Kartentipplerjargon', 'ein Bummerl klopfen', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"ein Bummerl ausspielen\""}, {"kategorie": "", "text": "\"eine volle Runde [[Schnapsen]] durchspielen\""}, {"kategorie": "", "text": "eine Partie Schnapsen bis zum letzten Punkt ausspielen"}]'::jsonb, ''),
  ('oida-hau-ma-uns-auf-an-schnopsa-und-klopf-ma-a-schnoeoes-bummal-aus', 'Oida, hau ma uns auf an Schnopsa und klopf ma a schnöös Bummal aus!', '', '', '', 'Wiener Kartentipplerjargon', 'Alter, hauen wir uns auf einen Schnapser und klopfen wir ein schnelles Bummerl!', '[{"kategorie": "wörtlich", "text": "\"Na komm, setzen wir uns auf eine Schnapspartie zusammen und klopfen wir ein schnelles Bummerl!\"  2. Komm, hock dich her auf eine Runde Schnapsen - ein schnelles Bummerl ist immer drin!  3. Lust auf einen Schnapser? Komm, spielen wir uns ein schnelles Bummerl aus!"}]'::jsonb, ''),
  ('a-schduella-geniissa-oda-wia-da-koowara-soong-daed-a-bippla-mit-nivoo', 'A schdülla Geniissa - oda wia da Koowara soong däd: ''A Bippla mit Nivoo!''', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein stiller Genießer – oder, wie der Koberer sagen täte: ein Pippler mit Niveau!', '[{"kategorie": "wörtlich", "text": "\"Ein stiller Genießer – oder, wie der Wirt sagt: ein Pippler mit Niveau!\"  2. Ein Freund des guten Tropfens – oder, wie der Wirt sagen würde: ''ein Genusstrinker - immer niveauvoll und immer voll!''  3. Ein stiller Prophet des Hochprozentigen - oder, wie der Wirt sagen würde: ''Trinkt wie ein Heiliger''!"}]'::jsonb, ''),
  ('ois-oida-schnopsbippla-kennda-jeede-hausbrennarei-im-umkreis-von-30-kilomaeaeta', 'Ois oida Schnopsbippla kennda jeede Hausbrennarei im Umkreis von 30 Kilomääta!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Als alter Schnapspippler kennt er jede Hausbrennerei im Umkreis von 30 Kilometern!', '[{"kategorie": "wörtlich", "text": "\"Als alter Schnapssüffler kennt er jede Hausbrennerei im Umkreis von 30 Kilometern!\"  2. Als passionierter Schnapstrinker kennt er jede private Brennerei im Umkreis von 30 Kilometern - und kehrt dort auch regelmäßig ein, um Hochprozentiges zu verkosten!  3. In Sachen Hausbrände ist er als Genusstrinker mit den regionalen Schnapsquellen bestens vertraut!"}]'::jsonb, ''),
  ('es-gibd-kaan-heirichn-bei-dem-da-oide-weibippla-ned-aufkreizd', 'Es gibd kaan Heirichn, bei dem da oide Weibippla ned aufkreizd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Es gibt keinen Heurigen, bei dem der alte Weinpippler nicht aufkreuzt!', '[{"kategorie": "wörtlich", "text": "\"Es gibt keinen Heurigen, bei dem der alte Weintrinker nicht aufkreuzt!\"  2. Wo Wein ausgeschenkt wird, ist dieser Schluckspecht nicht weit!  3. Als passionierter Weinliebhaber kennt er alle Lokale in der Umgebung und weiß auswendig, wann genau sie ausgesteckt haben!"}]'::jsonb, ''),
  ('i-glaub-es-gibd-kaa-wiatshausbrauarei-wo-dea-oide-biabippla-ned-scho-aufkreizd-is', 'I glaub, es gibd kaa Wiatshausbrauarei, wo dea oide Biabippla ned scho aufkreizd is!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich glaube, es gibt keine Wirtshausbrauerei, wo dieser alte Bierpippler nicht schon aufgekreuzt ist!', '[{"kategorie": "wörtlich", "text": "\"Ich glaube, es gibt keine Wirtshausbrauerei, bei der dieser Biersüffler nicht aufkreuzt!\"  2. Wo Bier ausgeschenkt wird, ist dieser Schluckspecht nicht weit!  3. Als passionierter Bierliebhaber kennt er alle Wirtshausbrauereien nicht nur in der Umgebung, sondern im ganzen Land!"}]'::jsonb, ''),
  ('de-zwaa-schdampalbriada-saufn-rund-umd-uua-bruadaschofd-mitnaund', 'De zwaa Schdampalbriada saufn rund umd Uua Bruadaschofd mitnaund!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die zwei Stamperlbrüder saufen rund um die Uhr Bruderschaft miteinander!', '[{"kategorie": "wörtlich", "text": "\"Die beiden Schnapsbrüder saufen rund um die Uhr Bruderschaft miteinander!\"  2. Die zwei Schnapssüffler sind ein Herz und eine Seele - sie trinken rund um die Uhr Bruderschaft miteinander!  3. Die beiden Schnapszuzler trinken rund um die Uhr Bruderschaft miteinander und busseln sich im Suff ständig ab!"}]'::jsonb, ''),
  ('a-schnopsbruada-trinkd-weeniga-zum-vagessn-ois-zua-vatiefung', 'A Schnopsbruada trinkd weeniga zum Vagessn ois zua Vatiefung!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Schnapsbruder trinkt weniger zum Vergessen als zur Vertiefung!', '[{"kategorie": "wörtlich", "text": "\"Als Schnapsbruder sucht er im Feuerwasser nicht das Vergessen, sondern den geistigen Tiefgang!\"  2. Ein Schnapsbruder säuft sich nicht weg, sondern gescheit!  3. Der Schnapspippler sagt, Hochprozentiges löscht bei ihm keine Gedanken, sondern brennt sie nur tiefer ein!"}]'::jsonb, ''),
  ('a-schnopszuuzla-kippd-in-schnops-ned-aafoch-owe-na-ea-zuuzld-eam', 'A Schnopszuuzla kippd in Schnops ned aafoch owe - na, ea zuuzld eam!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Schnapszuzler kippt den Schnaps nicht einfach runter - nein, er zuzelt ihn!', '[{"kategorie": "wörtlich", "text": "\"Ein Schnapszuzler kippt den Schnaps nicht einfach runter - nein, er lutscht ihn!\"  2. Bei einem Schnapszuzler gibt''sein Runterkippen - der zieht den Schnaps durch die Zähne wie ein Staubsauger!  3. Guter Schnaps kommt langsam – ein echter Zuzler weiß das!"}]'::jsonb, ''),
  ('de-schnopsnoosn-kennd-mea-suatn-obstbraund-ois-a-brennmaasta', 'De Schnopsnoosn kennd mea Suatn Obstbraund ois a Brennmaasta!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die Schnapsnase kennt mehr Sorten Obstbrand als ein Brennmeister!', '[{"kategorie": "wörtlich", "text": "\"Die Saufnase hat mehr Schnapssorten im Kopf als der Brennmeister im Lager!\"  2. Wenn Schnapsnasen Doktorarbeiten über Obstbrände schreiben müssten, dann wär er der Universitätsprofessor!\" 3. Er hat sein Leben nicht verschwendet – er hat es in Spirituosen investiert. Nobelpreis in Schnapsologie!  3. Der hat mehr Schnapssorten im Kopf als der Brennmeister im Lager!"}]'::jsonb, ''),
  ('dea-oide-schnopsla-kennd-jeede-hausbrennarei-im-umkreis-von-30-kilomaeaeta', 'Dea oide Schnopsla kennd jeede Hausbrennarei im Umkreis von 30 Kilomääta!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der alte Schnapsler kennt jede Hausbrennerei im Umkreis von 30 Kilometern!', '[{"kategorie": "wörtlich", "text": "\"Der alte Schnapssüffler kennt jede Hausbrennerei im Umkreis von 30 Kilometern!\"  2. Als passionierter Schnapstrinker kennt er jede private Brennerei im Umkreis von 30 Kilometern - und kehrt dort auch regelmäßig ein, um Hochprozentiges zu verkosten!  3. In Sachen Hausbrände gilt er als erfahrener Genusstrinker, der mit den regionalen Schnapsquellen bestens vertraut ist!"}]'::jsonb, ''),
  ('i-hob-s-laawal-wulaeae-gnumma-und-zack-drin-woara', 'I hob s''Laawal wulää gnumma - und zack, drin woara!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ich hab das Laberl volley genommen - und zack, drin war er!', '[{"kategorie": "wörtlich", "text": "\"Ich hab den Ball volley genommen - und zack, drin war er!\"  2. Ich hab die Kugel volley genommen – und eiskalt versenkt!  3. Ich nahm den Ball direkt aus der Luft – und im nächsten Augenblick zappelte er bereits im Netz!"}]'::jsonb, ''),
  ('wea-soiche-laawaln-hod-brauchd-kan-eeabaeaeg', 'Wea soiche Laawaln hod, brauchd kan Eeabääg!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Wer solche Laberln hat, braucht keinen Airbag!', '[{"kategorie": "wörtlich", "text": "\"Wer einen solchen Vorbau hat, braucht keinen Airbag!\"  2. Mit den zwei Tutteln vorn brauchst keinen Airbag mehr!  3. Das ist kein Busen – das ist eine Fünf-Sterne-Knautschzone!"}]'::jsonb, ''),
  ('zum-laawal-wean', 'zum Laawal wean', '', '', '', 'Wiener Sprüche, die sitzen!', 'zum Laberl werden', '[{"kategorie": "wörtlich", "text": "\"weich werden\" (quasi \"auseinanderfallen wie ein formloses [[Laberl]]\""}, {"kategorie": "fig.", "text": "\"zusammenklappen\", \"sich nicht mehr halten können\" (vor Freude, Erstaunen, Empörung oder Entsetzen), \"den Boden unter den Füßen verlieren\""}]'::jsonb, 'Do wiasd zum Laawal, waunnsd soowos mitauschaun muassd!'),
  ('do-wiasd-zum-laawal-waunnsd-soowos-mitauschaun-muassd', 'Do wiasd zum Laawal, waunnsd soowos mitauschaun muassd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da wirst du zum Laberl, wenn du sowas mitanschauen musst!', '[{"kategorie": "wörtlich", "text": "\"Da fällst du auseinander wie ein weiches Laberl, wenn du sowas mitansehen musst!\"  2. Da verlierst den Boden unter den Füßen, wenn du sowas siehst!  3. Das haut dich emotional komplett aus der Bahn, wenn du sowas selbst miterleben musst!"}]'::jsonb, 'zum Laawal wean'),
  ('wachaua-laawal', 'Wachaua Laawal', 'das', '', '', 'Wiener Küche & Gaumenfreuden', 'Wachauer Laberl', '[{"kategorie": "wörtlich", "text": "\"Wachauer Laibchen\" (kleines, rundes Weizenbrötchen aus der österreichischen Bäckereitradition, benannt nach der [[Wachau]] [Flußtal entlang der Donau zwischen Melk und Krems, berühmt auch für Wein, Marillen (Aprikosen) und traditionelle Kulinarik], In der Form einem kleinen Laib Brot nachempfunden, daher \"Laibchen\")"}, {"kategorie": "allg.", "text": "\"semmelartiges Graugebäck aus Weizen- und Roggenmehl\", \"kleines, rundes Graugebäck\" (etwas größer als eine Semmel)"}]'::jsonb, 'Tradition zum Aubeissn: Unsare Wachaua Laawaln - täglich frisch ausn Schdaaoofn!'),
  ('tradition-zum-aubeissn-unsare-wachaua-laawaln-taeglich-frisch-ausn-schdaaoofn', 'Tradition zum Aubeissn: Unsare Wachaua Laawaln - täglich frisch ausn Schdaaoofn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Tradition zum Anbeißen: Unsere Wachauer Laibchen – täglich frisch aus dem Steinofen!', '[{"kategorie": "wörtlich", "text": "\"Echte Handwerkskunst: Wachauer Laibchen – täglich frisch im Steinofen gebacken, knusprig, frisch, traditionell!\"  2. Wachauer Laibchen - ofenwarm, handgemacht, aus’m Herzen der Wachau!  3. Wo Handwerk Herz trifft – da kommen Wachauer Laibchen aus dem Ofen!"}]'::jsonb, 'Wachaua Laawal'),
  ('a-reschs-schuastalaawal-mit-oliivnoeoe-und-soiz-mei-lieblingsjausn', 'A reschs Schuastalaawal mit Oliivnöö und Soiz - mei Lieblingsjausn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein resches Schusterlaberl mit Olivenöl und Salz – meine Lieblingsjause!', '[{"kategorie": "wörtlich", "text": "\"Ein knuspriges Schusterlaberl mit Olivenöl und Salz – das ist mein Lieblingssnack!\"  2. Knuspriges Brötchen, gutes Olivenöl, ein wenig Salz – mein einfacher Genuss für zwischendurch!  3. Oval, eingekerbt, frisch und knusprig - ein Schusterlaberl mit Öl und ein wenig Salz ist schlicht unwiderstehlich!"}]'::jsonb, ''),
  ('waunn-i-richtig-hunga-hob-beschdoeoe-i-ma-a-fiakagulasch-des-hoid-laenga-sott-ois-ollas-aundare', 'Waunn I richtig Hunga hob, beschdöö I ma a Fiakagulasch - des hoid länga sott ois ollas aundare!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn ich richtig Hunger habe, bestelle ich mir ein Fiakergulasch – das hält länger satt als alles andere!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich ordentlich Hunger habe, greife ich zum Fiakergulasch – das ist eine köstliche und richtig sättigende Mahlzeit!\"  2. Bei großem Hunger gibt’s für mich nur eins: Fiakergulasch. Das macht garantiert satt!  3. Wenn der Magen richtig knurrt, kommt ein Fiakergulasch auf den Tisch – das hält, was es verspricht!"}]'::jsonb, ''),
  ('fia-a-richtigs-gulasch-nimm-i-imma-an-woodschunkn-dea-bleibd-aa-beim-dinstn-schee-softig', 'Fia a richtigs Gulasch nimm I imma an Woodschunkn - dea bleibd aa beim Dinstn schee softig!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Für ein richtig gutes Gulasch nehme ich immer einen Wadschinken – der bleibt auch beim Dünsten schön saftig!', '[{"kategorie": "wörtlich", "text": "\"Für ein richtig gutes Gulasch nehme ich immer ausgelöstes Rindfleisch vom unteren Teil der Keule – das bleibt auch beim Schmoren schön saftig!\"  2."}]'::jsonb, ''),
  ('da-intensive-gschmockn-vom-majoranfleisch-kummd-vom-laungan-dinstn-und-von-da-typischen-wiina-gewueazmischung-aus-majoran-pfeffa-und-loabeablaadl', 'Da intensive Gschmockn vom Majoranfleisch kummd vom laungan Dinstn und von da typischen Wiina Gewüazmischung aus Majoran, Pfeffa und Loabeablaadl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der intensive Geschmack des Majoranfleischs entsteht durch langes Dünsten und den typischen Wiener Gewürzmix mit Majoran, Pfeffer und Lorbeerblatt!', '[{"kategorie": "wörtlich", "text": "\"Sein kräftiges Aroma verdankt das Majoranfleisch dem langsamen Dünsten und der klassischen Wiener Würzung mit Majoran, Pfeffer und Lorbeer!\"  2. Seinen vollmundigen Geschmack entfaltet das Majoranfleisch durch behutsames Schmoren und die traditionelle Würze mit Majoran, Pfeffer und Lorbeer!  3. Sorgfältiges Dünsten und die Verwendung von Majoran, Pfeffer und Lorbeer verleihen dem Wiener Majoranfleisch seinen unverwechselbaren Geschmack!"}]'::jsonb, ''),
  ('a-guad-greifda-toofaeschbitz-mit-feina-marmorierung-is-a-bsundas-softigs-fleisch-zum-dinstn', 'A guad greifda Toofäschbitz mit feina Marmorierung is a bsundas softigs Fleisch zum Dinstn!', '', '', '', 'Wiener Fleischhauer-Slang', 'Ein gut gereifter Tafelspitz mit feiner Marmorierung ist ein besonders saftiges Fleisch zum Dünsten!', '[{"kategorie": "wörtlich", "text": "\"Ein gut gereifter Tafelspitz mit feiner Marmorierung ergibt ein besonders saftiges Siedefleisch!\"  2. Reife und Marmorierung machen den Tafelspitz zur idealen Wahl für saftiges Kochfleisch"}, {"kategorie": "", "text": "Dank seiner feinen Fettäderung wird der Tafelspitz beim Sieden besonders aromatisch und mürbe!"}]'::jsonb, ''),
  ('beim-plachutta-beschdoeoe-i-ma-imma-an-toofaschbitz-mit-markknochn-des-hod-bei-uns-in-wien-kaisaliche-tradition', 'Beim Plachutta beschdöö I ma imma an Toofaschbitz mit Markknochn - des hod bei uns in Wien kaisaliche Tradition!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Beim Plachutta bestell ich mir immer Tafelspitz mit Markknochen – das hat bei uns in Wien kaiserliche Tradition!', '[{"kategorie": "wörtlich", "text": "\"Beim Plachutta genieße ich traditionell gekochten Tafelspitz mit Markknochen – ein kulinarisches Erbe der kaiserlichen Hofküche!\" (Zur Erklärung: Der Tafelspitz kam im 19. Jahrhundert auf und wurde besonders durch die Küche am kaiserlichen Hof in Wien [Hofküche der Habsburger] geprägt. Kaiser [[Franz]] Joseph I. soll ein großer Liebhaber von gekochtem Rindfleisch gewesen sein – vor allem auch vom Tafelspitz. \"Plachutta\" ist eine berühmte, traditionsreiche Wiener Restaurantgruppe [benannt nach deren Gründer, Meisterkoch Ewald Plachutta], die sich besonders auf klassische österreichische Küche spezialisiert hat – mit dem Tafelspitz als kulinarischem Aushängeschild)"}, {"kategorie": "", "text": "\"In Wien isst man Tafelspitz – und beim Plachutta besonders gern mit Markknochen dazu!\"  3. \"Für mich gibt’s beim Plachutta nur eines: Tafelspitz mit Markknochen – ein Rindfleischklassiker mit Geschichte!\""}]'::jsonb, ''),
  ('des-toofaeschdickl-zoeoed-zu-d-bestn-gustoschdickln-vom-rind-und-is-peafekt-zum-kochn-dinstn-oda-broodn', 'Des Toofäschdickl zööd zu d''bestn Gustoschdickln vom Rind und is peafekt zum Kochn, Dinstn oda Broodn!', '', '', '', 'Wiener Fleischhauer-Slang', 'Das Tafelstückl zählt zu den besten Gustostückeln vom Rind und ist perfekt zum Kochen, Dünsten oder Braten!', '[{"kategorie": "wörtlich", "text": "\"Das Tafelstückl zählt zu den besten Gustostücken vom Rind und eignet sich hervorragend zum Kochen, Schmoren oder Braten!\"  2. Das Tafelstückl stammt aus dem Schlögel des Rindes und entfaltet beim Schmoren und Kochen seine volle Qualität!  3. Ein Gustostück der Wiener Küche: Das Tafelstückl – fein marmoriert, saftig und vielseitig!"}]'::jsonb, ''),
  ('semmaegree-mochd-ma-mit-eigwaakde-semmaen-in-aana-haassn-rindsuppn-und-vafeinad-des-gaunze-daunn-mit-frisch-griibanan-gree-de-peafekte-beiloog-zum-toofaeschbitz', 'Semmägree mochd ma mit eigwaakde Semmän in aana haassn Rindsuppn und vafeinad des Gaunze daunn mit frisch griibanan Gree - de peafekte Beiloog zum Toofäschbitz!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Semmelkren macht man mit eingeweichten Semmeln in einer heißen Rindsuppe und verfeinert das Ganze dann mit frisch geriebenem Kren - die perfekte Beilage zum Tafelspitz!', '[{"kategorie": "wörtlich", "text": "\"Für Semmelkren weicht man Semmeln in kräftiger Rindssuppe ein und verfeinert die Masse dann mit frisch geriebenem Kren – die perfekte Beilage zum [[Tafelspitz]]!\"  2. Semmelkren bereitet man zu, indem man Semmeln in kräftiger Rindersuppe einweicht und mit frisch geriebenem Meerrettich abschmeckt – die ideale Begleitung zum Wiener Tafelspitz!  3. Für eine traditionelle Semmelkren-Sauce werden in Rindsuppe aufgeweichte Semmeln mit scharfem Kren verrührt – ein Muss zum Wiener Tafelspitz!"}]'::jsonb, ''),
  ('opfaegree-mochd-ma-mit-eigwaakde-aepfaen-in-aana-haassn-rindsuppn-und-vafeinad-des-gaunze-daunn-mit-frisch-griibanan-gree-de-peafekte-beiloog-zum-toofaeschbitz', 'Opfägree mochd ma mit eigwaakde Äpfän in aana haassn Rindsuppn und vafeinad des Gaunze daunn mit frisch griibanan Gree - de peafekte Beiloog zum Toofäschbitz!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Apfelkren macht man mit eingeweichten Äpfeln in einer heißen Rindsuppe und verfeinert das Ganze dann mit frisch geriebenem Kren - die perfekte Beilage zum Tafelspitz!', '[{"kategorie": "wörtlich", "text": "\"Für Apfelkren weicht man Äpfel in kräftiger Rindssuppe ein und verfeinert die Masse dann mit frisch geriebenem Kren – die perfekte Beilage zum [[Tafelspitz]]!\"  2. Apfelkren bereitet man zu, indem man Äpfel in kräftiger Rindersuppe einweicht und mit frisch geriebenem Meerrettich abschmeckt – die ideale Begleitung zum Wiener Tafelspitz!  3. Für eine traditionelle Apfelkren-Sauce werden in Rindsuppe aufgeweichte Äpfel mit scharfem Kren verrührt – ein Muss zum Wiener Tafelspitz!"}]'::jsonb, ''),
  ('eadaepfaeroesti-goidbraun-broodn-passn-wundaboa-zum-toofaeschbitz', 'Eadäpfärösti, goidbraun broodn, passn wundaboa zum Toofäschbitz!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Erdäpfelrösti, goldbraun gebraten, passen wunderbar zum Tafelspitz!', '[{"kategorie": "wörtlich", "text": "\"Erdäpfelrösti, goldbraun gebraten, passen hervorragend zum klassischen Wiener Tafelspitz!\"  2. Goldene Rösti aus Kartoffeln sind eine harmonische Beilage zum klassischen Wiener Tafelspitz!  3. Knusprig gebratene Erdäpfelrösti ergänzen den Wiener Tafelspitz ideal in Geschmack und Textur!"}]'::jsonb, ''),
  ('roesti-goidbraun-broodn-passn-wundaboa-zum-toofaeschbitz', 'Rösti, goidbraun broodn, passn wundaboa zum Toofäschbitz!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Rösti, goldbraun gebraten, passen wunderbar zum Tafelspitz!', '[{"kategorie": "wörtlich", "text": "\"Rösti, goldbraun gebraten, passen hervorragend zum klassischen Wiener Tafelspitz!\"  2. Goldene Rösti aus Kartoffeln sind eine harmonische Beilage zum klassischen Wiener Tafelspitz!  3. Knusprig gebratene Erdäpfelrösti ergänzen den Wiener Tafelspitz ideal in Geschmack und Textur!"}]'::jsonb, ''),
  ('moogas-meisl', 'Moogas Meisl', 'das', '', '', 'Wiener Fleischhauer-Slang', 'Mageres Meisl', '[{"kategorie": "wörtlich", "text": "\"Mageres Meisel\" (eigtl. \"Mäusel\", Verkleinerungsform von \"Maus\", vom mittelhochdeutschen \"mūs\"=\"Maus\" bzw. \"Muskel\")"}, {"kategorie": "Fleischhauerjargon", "text": "Rinderschnittstück, Gustostück vom vorderen Schulterblattmuskel des Rindes, \"Fleisch aus der Schulterspitze\" (Spezialität der Wiener Küche, ideal u.a. auch für [[Tafelspitz]] und [[Majoranfleisch]], etc.)"}]'::jsonb, 'Im Untaschiid zum Schuitascheazl is des moogare Meisl bsundas fettoam, owa trotzdem gschmackig!'),
  ('im-untaschiid-zum-schuitascheazl-is-des-moogare-meisl-bsundas-fettoam-owa-trotzdem-gschmackig', 'Im Untaschiid zum Schuitascheazl is des moogare Meisl bsundas fettoam, owa trotzdem gschmackig!', '', '', '', 'Wiener Fleischhauer-Slang', 'Im Unterschied zum Schulterscherzel ist das magere Meisel besonders fettarm, aber trotzdem g''schmackig!', '[{"kategorie": "wörtlich", "text": "\"Im Unterschied zum Schulterscherzel ist das magere Meisel besonders fettarm, aber dennoch geschmackvoll!\"  2. Im Vergleich zum Schulterscherzel enthält das magere Meisel deutlich weniger Fett, überzeugt jedoch mit vollem Geschmack!  3. Während das Schulterscherzel stärker marmoriert ist, punktet das magere Meisl mit feinerem Fleisch und weniger Fett!"}]'::jsonb, 'Moogas Meisl'),
  ('de-fleedamaus-sitzd-direkt-aum-kreizbaa-vom-rind-muassd-sauwa-ausloeoesn-sunst-dawischd-in-seenanaunsotz', 'De Fleedamaus sitzd direkt aum Kreizbaa vom Rind - muassd sauwa auslöösn, sunst dawischd in Seenanaunsotz!', '', '', '', 'Wiener Fleischhauer-Slang', 'Die Fledermaus sitzt direkt am Kreuzbein – musst sauber rauslösen, sonst erwischst du den Sehnenansatz!', '[{"kategorie": "wörtlich, Fleischerjargon", "text": "\"Das Fledermausstück liegt unmittelbar am Kreuzbein – beim Auslösen muss man auf die Sehnen achten, sonst schneidet man sie mit raus!\"  2. Die Fledermaus liegt tief am Beckenknochen – sauber parieren, sonst ist das Stück von Sehnen durchzogen!  3. Direkt beim Kreuzbein sitzt die Fledermaus – beim Herauslösen muss man exakt arbeiten, um Bindegewebsanteile zu vermeiden!"}]'::jsonb, '')
